# ---------------------------------------------------------------- planner: plan.json = {requirements, readings, units}
_UID_RX = re.compile(r"^[A-Za-z][A-Za-z0-9_-]{0,63}$")

HISTORY = ("failed",)   # retired units stay in the plan as history; their ids are never reused


def _in_unit_dir(uid, n):
    return n == "/workspace/%s" % uid or n.startswith("/workspace/%s/" % uid)


def plan_alloc_min(u):
    """The minutes of wall a unit owns on the critical path - alloc_min for a produce unit, report_cost_min for the
    render unit, 0 for a unit that is already finished or retired (its time is spent, not planned)."""
    u = u or {}
    if u.get("status") == "done" or u.get("status") in HISTORY:
        return 0
    if u.get("type") == "render":
        try:
            return max(REPORT_COST_BOUNDS[0], min(REPORT_COST_BOUNDS[1], int(float(u.get("report_cost_min")))))
        except Exception:
            return REPORT_MIN
    try:
        return max(0, int(float(u.get("alloc_min"))))
    except Exception:
        return 0


def critical_path(plan):
    """(minutes, [ids]) of the longest depends_on chain of alloc_min, the render unit's report cost included."""
    by = dict((u.get("id"), u) for u in (plan or []) if isinstance(u, dict))
    memo = {}
    def walk(uid, seen=()):
        if uid in memo:
            return memo[uid]
        best = (0, [])
        for d in ((by.get(uid) or {}).get("depends_on") or []):
            if d in by and d not in seen and d != uid:
                c = walk(d, seen + (uid,))
                if c[0] > best[0]:
                    best = c
        memo[uid] = (best[0] + plan_alloc_min(by.get(uid)), best[1] + [uid])
        return memo[uid]
    out = (0, [])
    for u in (plan or []):
        if not isinstance(u, dict) or u.get("status") in HISTORY:
            continue
        c = walk(u.get("id"))
        if c[0] > out[0]:
            out = c
    return out


def plan_shape(plan):
    """The dependency shape of the live produce units -> {"width0": units that can start at t=0, "depth": longest produce chain,
    "gate": the one root every other produce unit hangs on (or None), "fan_in": [(uid, [independent producers it waits on])]}."""
    by = dict((u.get("id"), u) for u in (plan or []) if isinstance(u, dict))
    live = [u for u in (plan or []) if isinstance(u, dict) and u.get("type") == "produce" and u.get("status") not in HISTORY]
    def live_deps(u):
        return [d for d in (u.get("depends_on") or []) if d in by and by[d].get("type") == "produce" and by[d].get("status") not in HISTORY]
    memo = {}
    def depth(uid, seen=()):
        if uid in memo:
            return memo[uid]
        ds = [depth(d, seen + (uid,)) for d in live_deps(by[uid]) if d not in seen and d != uid]
        memo[uid] = 1 + (max(ds) if ds else 0)
        return memo[uid]
    def anc(uid, seen=()):
        out = set()
        for d in live_deps(by.get(uid) or {}):
            if d not in seen and d != uid:
                out.add(d); out |= anc(d, seen + (uid,))
        return out
    roots = [u["id"] for u in live if not live_deps(u)]
    gate = None
    if len(live) >= 3 and len(roots) == 1 and all(roots[0] in anc(u["id"]) for u in live if u["id"] != roots[0]):
        gate = roots[0]
    fan_in = []
    for u in live:
        ds = live_deps(u)
        if len(ds) >= 2 and not any(a in anc(b) or b in anc(a) for a in ds for b in ds if a != b):
            fan_in.append((u["id"], ds))
    return {"width0": len(roots), "depth": max([depth(u["id"]) for u in live] or [0]), "gate": gate, "fan_in": fan_in}


def _crit_has_number(c):
    """Does a done criterion state a number (paths, file names, unit ids and F-references removed)?"""
    s = re.sub(r"\S*/\S*", " ", c)
    s = re.sub(r"\b[\w.-]+\.(?:py|json|npz|npy|csv|tsv|txt|png|pdf|dat|h5|hdf5|md|log|jl)\b", " ", s)
    s = re.sub(r"\b[uU]\d+\b|\bF\d+\b", " ", s)
    return bool(re.search(r"\d", s))


def plan_summary(plan):
    L = ["PLAN SUMMARY (%d units; node %d cores / %s GB):" % (len(plan), NCPUS, MEM_GB or "?")]
    for u in plan:
        L.append("  %-6s %-8s cores=%-3s mem=%-4s deps=%-18s %s%s" % (
            u.get("id"), u.get("type"), u.get("cores"), u.get("mem_gb"),
            ",".join(str(x) for x in (u.get("depends_on") or [])) or "-",
            (str(u.get("goal", "")).splitlines() or [""])[0][:90],
            (" [%s]" % u.get("status")) if u.get("status") else ""))
    return "\n".join(L)

_NEG_BEFORE = re.compile(r"\b(never|not|no|none|don't|do not|must not|may not|cannot|can't|nor|without|forbid\w*|prohibit\w*|disallow\w*)\b", re.I)
_NEG_AFTER = re.compile(r"\b(forbidden|prohibited|disallowed|not allowed|not permitted|never)\b", re.I)
_CLAUSE_END = re.compile(r"[.;:!?,\n]")
_DROP_RX = re.compile(r"\b(drop(?:ped|ping|s)?|omit(?:ted|s)?|skip(?:ped|s)?|sacrific\w*|leave out|left out|mark(?:ed)?(?: it| them)? (?:as )?missing|as missing)\b", re.I)
_FALLBACK_RX = re.compile(r"\b(fall ?back|fallback|in place of|instead of|substitut\w*|stand-?in|approximat\w* (?:it|them) by)\b", re.I)

def _unnegated(rx, text):
    """Phrases of `text` matching rx that no negation in the same clause qualifies ("no required row may be dropped", "never drop", "a substitute
    is forbidden" are compliance, not authorisation)."""
    out, text = [], text or ""
    for m in rx.finditer(text):
        start = max([c.end() for c in _CLAUSE_END.finditer(text, 0, m.start())] or [0])
        e = _CLAUSE_END.search(text, m.end())
        if _NEG_BEFORE.search(text[start:m.start()]) or _NEG_AFTER.search(text[m.end():(e.start() if e else len(text))]):
            continue
        out.append(text[max(0, m.start() - 50):m.end() + 50].replace("\n", " "))
    return out

def need_paths(text, dep=None):
    """ONE path extractor for a "needs" entry, shared by the plan validator and the file gate: every /workspace/<dep>/... token
    ("A and B", "A plus B", "A (plus B)", "A + B", "A, B"), trailing punctuation stripped; placeholders (<key>, {a,b}, *) stay patterns."""
    toks = re.findall(r"/workspace/(?:[^\s,;'\"()\[\]{}]|\{[^{}]*\})+", str(text or ""))
    out = []
    for t in toks:
        t = t.rstrip(".:")
        if dep is not None and not (t == "/workspace/%s" % dep or t.startswith("/workspace/%s/" % dep)):
            continue
        if t.rstrip("/").endswith("/handoff.json"):
            continue
        if t not in out:
            out.append(t)
    return out

def split_plan(obj):
    """plan.json as written by the planner -> (units, requirements, readings, format error or None). A bare array is an old-style plan."""
    if isinstance(obj, list):
        return obj, None, None, None
    if isinstance(obj, dict) and isinstance(obj.get("units"), list):
        rq = obj.get("requirements")
        rd = obj.get("readings")
        return obj["units"], (rq if isinstance(rq, list) else None), (rd if isinstance(rd, list) else None), None
    return None, None, None, "plan.json must be a JSON object {\"requirements\": [...], \"readings\": [...], \"units\": [...]}"

def validate_plan(obj, old_plan=None, strict=True):
    """(errors, warnings, units, requirements, readings). Errors go back to the planner verbatim. HARD errors (the plan cannot run) are errors
    on every attempt; SOFT errors (the planning contract: requirements table, core first, allocation caps, drop / fallback wording) are errors
    while `strict`, warnings on the last attempt, so a plan always comes out. Uncited numbers in done_criteria never bounce a plan: they
    move to the unit's "notes". With old_plan (a replan) done / running / retired units are restored byte-identical."""
    errs, warns, soft = [], [], []
    plan, reqs, reads, ferr = split_plan(obj)
    if ferr:
        return [ferr], warns, None, None, None
    tb_n = len(task_book_items())
    if not plan or not all(isinstance(u, dict) for u in plan):
        return ["\"units\" must be a non-empty list of unit objects"], warns, None, None, None
    if not all(isinstance(u.get("id"), str) for u in plan):
        return ["every unit needs a string id"], warns, None, None, None
    for u in plan:   # the planner's free notes as a list (a string, number or null in its place is normalised)
        nt = u.get("notes")
        if not isinstance(nt, list):
            u["notes"] = [] if nt is None or (isinstance(nt, str) and not nt.strip()) else [nt if isinstance(nt, str) else json.dumps(nt)]
    if old_plan is not None:
        have = dict((u.get("id"), u) for u in plan)
        restored = []
        for ou in old_plan:
            st = ou.get("status") if isinstance(ou, dict) else None
            if st not in ("done", "running") + HISTORY:
                continue
            keep = json.loads(json.dumps(ou))
            nu = have.get(ou.get("id"))
            if nu is None:
                at = max([i + 1 for i, x in enumerate(plan) if x.get("id") in (keep.get("depends_on") or [])] or [0])
                plan.insert(at, keep)
                have[keep["id"]] = keep
                restored.append("%s (%s, missing -> re-inserted)" % (keep["id"], st))
            elif nu.get("status") != st or any(nu.get(k) != ou.get(k) for k in ("type", "goal", "deliverables", "done_criteria", "depends_on")):
                if st in HISTORY:
                    errs.append("unit %s: this id is RETIRED - a replacement needs a NEW id; keep the retired unit as it was or drop it" % keep["id"])
                nu.clear()
                nu.update(keep)
                restored.append("%s (%s, rewritten -> restored)" % (keep["id"], st))
        if restored:
            warns.append("replan: done / running / retired unit(s) restored from the live plan: %s" % ", ".join(restored))
    rends = [u for u in plan if u.get("type") == "render"]
    if len(rends) == 1:   # mechanical slips of the render unit are mended, never bounced: last in the list, depending on every produce unit
        rd0 = rends[0]
        if plan[-1] is not rd0:
            plan.remove(rd0); plan.append(rd0)
            warns.append("the render unit moved to the end of the plan")
        miss0 = [x["id"] for x in plan if x.get("type") == "produce" and x.get("status") not in HISTORY + ("done",) and x["id"] not in (rd0.get("depends_on") or [])]
        if miss0:
            rd0["depends_on"] = list(rd0.get("depends_on") or []) + miss0
            warns.append("the render unit now depends on %s too" % miss0)
    live = [u for u in plan if u.get("status") not in HISTORY]
    if len(live) < 2:
        errs.append("unit count %d below 2 (a produce unit and the render unit; retired units excluded)" % len(live))
    elif len(live) > MAX_UNITS:   # soft: on the last attempt a larger plan runs rather than the one-unit fallback
        soft.append("unit count %d above %d (retired units excluded): merge units" % (len(live), MAX_UNITS))
    ids = [u["id"] for u in plan]
    if len(set(ids)) != len(ids):
        errs.append("duplicate unit ids")
    by = dict((u["id"], u) for u in plan)
    pos = dict((u["id"], i) for i, u in enumerate(plan))
    wall_min = int(max(0.0, remaining()) // 60)
    for u in plan:
        uid = u["id"]
        tag = "unit %s" % uid
        hist = u.get("status") in HISTORY
        if not _UID_RX.match(uid):
            errs.append("%s: id must match %s" % (tag, _UID_RX.pattern))
        elif re.search(r"_(only|wrapup|gwretry\d*)$", uid):
            errs.append("%s: an id may not end in _only, _wrapup or _gwretry (the orchestrator's call suffixes)" % tag)
        errs += ["%s: missing %s" % (tag, k) for k in ("goal", "deliverables", "done_criteria") if k not in u]
        if not isinstance(u.get("deliverables"), list) or not u.get("deliverables") or not all(isinstance(x, str) and x.strip() for x in u["deliverables"]):
            errs.append("%s: deliverables must be a non-empty list of path strings" % tag)
        elif not hist:
            hj = [d for d in u["deliverables"] if d.strip().rstrip("/").endswith("/handoff.json")]
            if hj:
                u["deliverables"] = [d for d in u["deliverables"] if d not in hj]
                warns.append("%s: handoff.json is not a deliverable (dropped from the list)" % tag)
                if not u["deliverables"]:
                    errs.append("%s: deliverables must name at least one product besides handoff.json" % tag)
            for d in u["deliverables"]:
                n = d.strip().rstrip("/")
                if not _in_unit_dir(uid, n) and not (u.get("type") == "render" and re.match(r"^/workspace/[^/]+$", n)):
                    errs.append("%s: deliverable %r must be inside the unit's own directory /workspace/%s/%s"
                                % (tag, d, uid, " (the render unit may also name the final files at /workspace/ root)" if u.get("type") == "render" else ""))
        if not isinstance(u.get("done_criteria"), list) or not u.get("done_criteria"):
            errs.append("%s: done_criteria must be a non-empty list" % tag)
        elif not hist and tb_n:   # a number of the planner's own is not a criterion: it moves to "notes" (no bounce)
            keep_c, moved = [], []
            for c in u.get("done_criteria"):
                if isinstance(c, str) and _crit_has_number(c) and not any(1 <= int(k) <= tb_n for k in re.findall(r"\bF(\d+)\b", c)):
                    moved.append(c)
                else:
                    keep_c.append(c)
            if moved:
                u["done_criteria"] = keep_c or ["every deliverable exists and follows the task book"]
                u.setdefault("notes", [])
                u["notes"] = list(u["notes"]) + ["(planner number, not a criterion) " + c for c in moved]
                warns.append("%s: %d done criteria state a number without a task-book item - moved to notes (not criteria): %s"
                             % (tag, len(moved), "; ".join(c[:80] for c in moved[:3])))
        t = u.get("type")
        if t not in UNIT_TYPES:
            errs.append("%s: type must be one of %s (got %r)" % (tag, "/".join(UNIT_TYPES), t))
        elif t == "render" and uid != "render":
            errs.append('%s: the render unit\'s id must be exactly "render"' % tag)
        c = u.get("cores")
        if not (isinstance(c, int) and not isinstance(c, bool) and c >= 1):
            errs.append("%s: cores must be a positive integer (got %r)" % (tag, c))
        elif c > NCPUS:
            errs.append("%s: cores=%d exceeds the node's %d cores" % (tag, c, NCPUS))
        m = u.get("mem_gb")
        if not (isinstance(m, (int, float)) and not isinstance(m, bool) and m >= 1):
            errs.append("%s: mem_gb must be a positive number (got %r)" % (tag, m))
        elif MEM_GB > 0 and m > MEM_GB:
            errs.append("%s: mem_gb=%s exceeds the node's %d GB" % (tag, m, MEM_GB))
        deps = u.setdefault("depends_on", [])
        if not isinstance(deps, list):
            errs.append("%s: depends_on must be a list of unit ids" % tag)
            deps = []
        if t == "render" and not hist:   # the report accounts for every unit; a retired id in its list schedules nothing
            gone = [d for d in deps if d in by and by[d].get("status") in HISTORY]
            if gone:
                deps[:] = [d for d in deps if d not in gone]
                warns.append("unit render: retired dependency %s dropped (the report accounts for retired units)" % ", ".join(gone))
        for d in deps:
            if d not in by:
                errs.append("%s: depends_on unknown unit %r" % (tag, d))
            elif d == uid:
                errs.append("%s: depends on itself" % tag)
            elif by[d].get("status") in HISTORY and not hist and u.get("status") not in ("done", "running"):
                errs.append("%s: depends_on %s which is RETIRED" % (tag, d))
            elif pos[d] > pos[uid]:
                errs.append("%s: depends_on %s which is listed AFTER it - list dependencies first" % (tag, d))
        if t == "produce" and deps and not hist:
            needs = u.get("needs")
            if not isinstance(needs, dict):
                errs.append('%s: depends_on %s but no "needs" object naming, per dependency, the upstream FILE this unit cannot start without - '
                            'or drop the dependency (comparisons and conventions are not dependencies)' % (tag, deps))
            else:
                for d in deps:
                    if not need_paths(needs.get(d), d):
                        errs.append('%s: needs[%s] must name a file under /workspace/%s/ other than handoff.json (got %r)' % (tag, d, d, str(needs.get(d))[:80]))
        if t == "render" and u.get("report_cost_min") is not None:
            try:
                float(u.get("report_cost_min"))
            except Exception:
                warns.append("%s: report_cost_min is not a number - the default %d min is used" % (tag, REPORT_MIN))
                u.pop("report_cost_min", None)
        a = u.get("alloc_min")
        if t == "produce" and not hist:
            if not (isinstance(a, (int, float)) and not isinstance(a, bool) and a > 0):
                errs.append("%s: alloc_min must be a positive number of minutes (got %r)" % (tag, a))
            elif a > wall_min / 3.0 + 1:
                soft.append("%s: alloc_min %d exceeds a third of the %d min of wall left - split the unit along its independent inputs or lower its "
                            "precision plan" % (tag, int(a), wall_min))
        if t == "produce" and u.get("scale_knobs") is not None and not isinstance(u.get("scale_knobs"), list):
            warns.append("%s: scale_knobs must be a list of strings - ignored" % tag)
            u.pop("scale_knobs", None)
        if not hist and t == "produce":
            txt = " ".join([str(u.get("goal", ""))] + [str(x) for x in (u.get("scale_knobs") or [])] + [str(x) for x in (u.get("done_criteria") or [])])
            for ph in _unnegated(_DROP_RX, txt)[:2]:
                soft.append("%s: a goal / knob / criterion may drop a required row (\"...%s...\"): required rows are never optional - lower precision "
                            "instead, and let the review decide what does not fit" % (tag, ph.strip()))
            for ph in _unnegated(_FALLBACK_RX, str(u.get("goal", "")))[:2]:
                soft.append("%s: the goal names a fallback / substitute (\"...%s...\"): a method component the task book names is implemented as "
                            "named, with a library's implementation of it where one exists - no fallback clause" % (tag, ph.strip()))
    renders = [u for u in plan if u.get("type") == "render"]
    prods = [u for u in plan if u.get("type") == "produce" and u.get("status") not in HISTORY]
    if len(renders) != 1:
        errs.append("exactly ONE render unit is required (got %d)" % len(renders))
    else:
        rd = renders[0]
        if plan[-1] is not rd:
            errs.append("the render unit must be the LAST unit")
        missing = [p["id"] for p in prods if p["id"] not in (rd.get("depends_on") or []) and p.get("status") != "done"]
        if missing:
            errs.append("the render unit must depends_on every produce unit; missing %s" % missing)
    if not prods:
        errs.append("at least one produce unit is required")
    seen_scripts = {}
    for p in prods:
        for d in (p.get("deliverables") or []):
            nm = str(d).strip()
            if nm.endswith("/") or not re.search(r"\.(py|sh|jl|c|cpp|R|m)$", nm):
                continue
            b = os.path.basename(nm)
            if b in seen_scripts and seen_scripts[b] != p.get("id"):
                soft.append("units %s and %s both deliver a script named %r - give every unit's scripts distinct names (shared process space)"
                            % (seen_scripts[b], p.get("id"), b))
            seen_scripts.setdefault(b, p.get("id"))
    # ---- the requirements table (one owner per row, never optional) and the core-first rule
    prod_ids = set(p["id"] for p in prods) | set(u["id"] for u in plan if u.get("type") == "produce" and u.get("status") == "done")
    if reqs is None:
        soft.append("plan.json has no \"requirements\" list: write one row per required item of the task book (series x required value x panel, "
                    "and every named method component) with its owner, \"core\" and \"precision_target\"")
        reqs = []
    good = []
    for i, r in enumerate(reqs):
        if not isinstance(r, dict) or not str(r.get("what") or "").strip():
            soft.append("requirements[%d] must be an object with at least \"what\" and \"owner\"" % i)
            continue
        r.setdefault("id", "Q%d" % (i + 1))
        r["core"] = bool(r.get("core") is True or str(r.get("core")).lower() == "true")
        if isinstance(r.get("owner"), list) and len(r["owner"]) == 1:   # ["u1"] is u1
            r["owner"] = r["owner"][0]
        if not isinstance(r.get("owner"), str):
            soft.append("requirements %s (%s): owner must be ONE unit id (got %s) - split the row by producer or name the unit that produces it"
                        % (r.get("id"), str(r.get("what"))[:60], json.dumps(r.get("owner"))[:80]))
            continue
        if r.get("owner") == "render":   # a row the render unit delivers (figure files, report, a schematic panel) - never a computed core row
            r["core"] = False
            good.append(r)
            continue
        if r.get("owner") not in prod_ids:
            soft.append("requirements %s (%s): owner %r is not a unit of this plan" % (r.get("id"), str(r.get("what"))[:60], r.get("owner")))
            continue
        good.append(r)
    if good and not any(r["core"] for r in good):
        soft.append("no requirement row is marked \"core\": mark the rows that carry the organizing claim and the largest required size / value / time")
    live_by = dict((u["id"], u) for u in live)
    def start_min(uid, seen=()):
        best = 0
        for d in (live_by.get(uid) or {}).get("depends_on") or []:
            if d in live_by and d not in seen and live_by[d].get("status") not in ("done",):
                best = max(best, start_min(d, seen + (uid,)) + plan_alloc_min(live_by[d]))
        return best
    for r in good:
        if not r["core"]:
            continue
        ow = r["owner"]
        if (live_by.get(ow) or {}).get("status") in ("done", "running"):
            continue
        sm = start_min(ow)
        preds = [d for d in ((live_by.get(ow) or {}).get("depends_on") or []) if d in live_by and live_by[d].get("status") not in ("done",)]
        big = [d for d in preds if int(live_by[d].get("cores") or 0) > max(1, NCPUS // 2)]
        if sm > 180 or big:
            soft.append("core row %s (%s) is owned by %s, which starts only after %d min behind %s%s: owners of core rows start at t=0 or after "
                        "upstream units of at most 180 min and at most half the cores; run the smallest series beside the core, not before it"
                        % (r.get("id"), str(r.get("what"))[:60], ow, sm, ", ".join(preds) or "-", (" (%s use more than half the cores)" % ", ".join(big)) if big else ""))
    if reads is None:
        warns.append("plan.json has no \"readings\" list - READINGS.md will say so")
        reads = []
    reads = [x for x in reads if isinstance(x, dict) and str(x.get("reading") or "").strip()]
    for i, x in enumerate(reads):
        x.setdefault("id", "K%d" % (i + 1))
        if isinstance(x.get("check_by"), list) and len(x["check_by"]) <= 1:   # ["u1"] is u1, [] is none
            x["check_by"] = x["check_by"][0] if x["check_by"] else None
        if x.get("check_by") is not None and not isinstance(x.get("check_by"), str):
            warns.append("readings %s: check_by must be ONE unit id (got %s) - ignored" % (x.get("id"), json.dumps(x.get("check_by"))[:80]))
            x["check_by"] = None
        if x.get("check_by") and x.get("check_by") not in prod_ids:
            warns.append("readings %s: check_by %r is not a produce unit - ignored" % (x.get("id"), x.get("check_by")))
            x["check_by"] = None
    cp_min, cp_ids = critical_path(plan)
    if cp_min > wall_min:   # soft: the usable wall bounds every unit anyway
        soft.append("critical path %d min does not fit the %d min of wall left: %s" % (cp_min, wall_min, " + ".join("%s %d" % (x, plan_alloc_min(by.get(x))) for x in cp_ids)))
    elif cp_min > 0.6 * wall_min + 1:
        soft.append("critical path %d min exceeds 60%% of the %d min of wall left (%s): shorten the chain or its allocations"
                    % (cp_min, wall_min, " + ".join("%s %d" % (x, plan_alloc_min(by.get(x))) for x in cp_ids)))
    if strict:
        errs += soft
    else:
        warns += ["(accepted on the last attempt) " + s for s in soft]
    return errs, warns, plan, good, reads

READINGS_LOCK = threading.Lock()

def write_readings(reads):
    """/workspace/READINGS.md from the plan's readings (and later versions). Its content depends on the readings only (it is a consumed input);
    rendering and writing happen under one lock, so the newest readings are written last."""
    with READINGS_LOCK:
        _write_readings(reads)

def _write_readings(reads):
    L = ["# READINGS - the task-book interpretations every unit shares (from the plan)",
         "Use them as written. Evidence that one is wrong goes into handoff.json \"reading_issue\" (executors) or the \"reading_change\" field of the FIX_PLAN line (critics);",
         "never switch silently. A changed reading is marked with its version.", ""]
    if not reads:
        L.append("(the plan names no shared readings - take every setting from the task book's own words)")
    for x in reads:
        L.append("%s%s (%s): %s" % (x.get("id"), (" v%d" % x["version"]) if x.get("version", 1) > 1 else "", x.get("F") or "-", x.get("reading")))
        if x.get("why"):
            L.append("    why: %s" % str(x.get("why"))[:400])
        if x.get("options"):
            L.append("    options: %s" % json.dumps(x.get("options"), ensure_ascii=False)[:400])
        if x.get("check") and str(x.get("check")).lower() not in ("none", "-", "null"):
            L.append("    check: %s%s" % (str(x.get("check"))[:400], (" - run FIRST by %s; until its verdict the reading above stands" % x["check_by"]) if x.get("check_by") else ""))
        if x.get("changed"):
            L.append("    CHANGED (version %d): %s" % (x.get("version", 2), str(x.get("changed"))[:500]))
    tmp = os.path.join(WS, "READINGS.md.tmp.%d.%d" % (os.getpid(), threading.get_ident()))
    try:
        with open(tmp, "w") as f:
            f.write("\n".join(L) + "\n")
        os.replace(tmp, os.path.join(WS, "READINGS.md"))
    except Exception as e:
        log("READINGS.md write failed: %s" % e)

# ---------------------------------------------------------------- run state (unit threads + scheduler share it under STATE_LOCK)
STATE_F = os.path.join(PD, "state.json")
RUN = {"plan": [], "grades": {}, "failed": [], "replans": 0, "retired": [], "requirements": [], "readings": [], "scouts": 0}

def checkpoint():
    """plan.json (the units array, disk is truth) + state.json, atomically. The live dicts are snapshotted under STATE_LOCK with the C encoder
    (the pure-Python indent encoder raised on concurrent mutation) and written from the snapshot."""
    with STATE_LOCK:
        try:
            snap_plan = json.loads(json.dumps(RUN["plan"], default=str))
            snap_state = json.loads(json.dumps({"plan": RUN["plan"], "grades": RUN["grades"], "failed": RUN["failed"], "replans": RUN["replans"],
                                                "retired": RUN["retired"], "exec_sids": EXEC_SIDS, "report": REPORT, "override": OVERRIDE.is_set(),
                                                "last_look": LAST_LOOK, "ts": int(time.time())}, default=str))
        except Exception as e:
            log("state snapshot failed: %s" % e)
            return
        replanning = REPLANNING.is_set()
    try:
        if not replanning:
            _atomic_json_dump(snap_plan, os.path.join(PD, "plan.json"))
    except Exception as e:
        log("plan.json rewrite failed: %s" % e)
    try:
        _atomic_json_dump(snap_state, STATE_F)
    except Exception as e:
        log("state save failed: %s" % e)

def _handoff_summary(uid, limit=500):
    """One line about a unit's handoff.json for the planner / report prompts (the file itself is what agents read)."""
    try:
        h = json.load(open(os.path.join(unit_dir(uid), "handoff.json")))
        return "%d deliverable(s); key_numbers %s; known_limits %s" % (len(h.get("deliverables") or []), json.dumps(h.get("key_numbers"), ensure_ascii=False)[:limit],
                                                                       str(h.get("known_limits"))[:200])
    except Exception:
        return "(no readable handoff.json)"

def _minimal_plan():
    """No valid plan inside the planning budget: one produce unit for the whole figure + the render unit (generic; better than no attempt)."""
    wall_min = int(max(60, remaining() // 60))
    return [{"id": "u1", "type": "produce", "goal": "Reproduce every required series of the task book's figure with the method the task book names: "
             "validate the production code path on the smallest exactly solvable case, time one production step at the largest required value, "
             "then produce the full required set at the precision the budget allows, one file per point.",
             "deliverables": ["/workspace/u1/data/", "/workspace/u1/run.py"], "done_criteria": ["every required series of the task book has data files under /workspace/u1/data/"],
             "depends_on": [], "cores": max(1, NCPUS - 2), "mem_gb": max(1, int((MEM_GB or 16) * 0.8)), "alloc_min": max(30, int(wall_min * 0.55)),
             "scale_knobs": ["sample counts, tolerances and grid density the task book leaves free"]},
            {"id": "render", "type": "render", "goal": "Render the figure and write report.md from the data on disk.", "deliverables": ["/workspace/render/report.md"],
             "done_criteria": ["report.md accounts for every task-book item"], "depends_on": ["u1"], "cores": 2, "mem_gb": 8, "alloc_min": REPORT_MIN}]

def _repair_plan(obj):
    """The last parseable plan with its structural errors mended (ids, deliverables outside the unit, unknown or late dependencies, missing
    needs / alloc / criteria, resource overshoots, the render unit) - used when every planner attempt was rejected."""
    units = split_plan(obj)[0] or []
    units = [dict(u) for u in units if isinstance(u, dict) and isinstance(u.get("id"), str) and _UID_RX.match(u["id"]) and u.get("type") != "render"]
    seen, out = set(), []
    for u in units:
        if u["id"] in seen or u["id"] == "render":
            continue
        seen.add(u["id"])
        u["type"] = "produce"
        dl = [d for d in (u.get("deliverables") or []) if isinstance(d, str) and _in_unit_dir(u["id"], d.strip().rstrip("/")) and not d.strip().endswith("handoff.json")]
        u["deliverables"] = dl or ["/workspace/%s/data/" % u["id"]]
        if not isinstance(u.get("done_criteria"), list) or not u["done_criteria"]:
            u["done_criteria"] = ["every deliverable exists and follows the task book"]
        u["goal"] = str(u.get("goal") or "produce the required rows this unit owns")
        try:
            u["cores"] = max(1, min(NCPUS, int(u.get("cores") or 4)))
        except Exception:
            u["cores"] = 4
        try:
            u["mem_gb"] = max(1, min(MEM_GB or 10 ** 6, int(float(u.get("mem_gb") or 8))))
        except Exception:
            u["mem_gb"] = 8
        try:
            u["alloc_min"] = max(10, int(float(u.get("alloc_min"))))
        except Exception:
            u["alloc_min"] = 60
        out.append(u)
    ids = set(u["id"] for u in out)
    for u in out:
        u["depends_on"] = [d for d in (u.get("depends_on") if isinstance(u.get("depends_on"), list) else []) if isinstance(d, str) and d in ids and d != u["id"]]
        nd = u.get("needs") if isinstance(u.get("needs"), dict) else {}
        u["needs"] = dict((d, nd.get(d) if need_paths(nd.get(d), d) else "/workspace/%s/ - the upstream deliverables" % d) for d in u["depends_on"])
    ordered, placed = [], set()
    while len(ordered) < len(out):   # dependencies first (a cycle is broken by dropping the back edges)
        progress = False
        for u in out:
            if u["id"] not in placed and all(d in placed for d in u["depends_on"]):
                ordered.append(u); placed.add(u["id"]); progress = True
        if not progress:
            for u in out:
                if u["id"] not in placed:
                    u["depends_on"] = [d for d in u["depends_on"] if d in placed]
                    u["needs"] = dict((d, v) for d, v in u["needs"].items() if d in placed)
                    ordered.append(u); placed.add(u["id"])
                    break
    if not ordered:
        return None
    ordered.append({"id": "render", "type": "render", "goal": "Render the figure and write report.md from the data on disk.", "deliverables": ["/workspace/render/report.md"],
                    "done_criteria": ["report.md accounts for every task-book item"], "depends_on": [u["id"] for u in ordered], "cores": 2, "mem_gb": 8})
    rq = split_plan(obj)[1] or []
    rq = [r for r in rq if isinstance(r, dict) and isinstance(r.get("owner"), str) and (r["owner"] in ids or r["owner"] == "render")]
    rd = split_plan(obj)[2] or []
    return {"requirements": rq, "readings": rd, "units": ordered}

def _accept_plan(units, reqs, reads, obj, r, attempt, warns, replan):
    """Publish a validated plan: plan_full.json (the planner's object), plan.json (units array), requirements.json, READINGS.md."""
    with STATE_LOCK:
        RUN["requirements"] = list(reqs or [])
        n_read = len(RUN.get("readings") or [])
        if not replan:
            RUN["readings"] = [dict(x, version=(int(x.get("version")) if str(x.get("version") or "").isdigit() else 1)) for x in (reads or [])]
        else:   # the live readings stand (in-run changes included); a replan may only add new ids
            have = set(str(x.get("id")).upper() for x in (RUN.get("readings") or []))
            RUN["readings"] = list(RUN.get("readings") or []) + [dict(x, version=1) for x in (reads or []) if str(x.get("id")).upper() not in have]
    try:
        _atomic_json_dump({"requirements": RUN["requirements"], "readings": RUN["readings"], "units": units}, os.path.join(PD, "plan_full.json"))
        _atomic_json_dump(units, os.path.join(PD, "plan.json"))
        _atomic_json_dump(RUN["requirements"], os.path.join(PD, "requirements.json"))
    except Exception as e:
        log("plan files write failed: %s" % e)
    if not replan or len(RUN["readings"]) != n_read:
        write_readings(RUN["readings"])
    if not replan and not RUN.get("report_cost_min"):
        RUN["plan"] = units
        RUN["report_cost_min"] = report_cost_min()   # frozen: a later replan never moves the override instant
    ledger({"kind": "plan", "ok": True, "units": [u["id"] for u in units], "replan_of": replan["uid"] if replan else None,
            "requirements": len(RUN["requirements"]), "core_rows": sum(1 for x in RUN["requirements"] if x.get("core")),
            "readings": len(RUN["readings"]),
            "alloc_min": dict((u.get("id"), plan_alloc_min(u)) for u in units), "critical_path_min": critical_path(units)[0],
            "shape": dict((k, v) for k, v in plan_shape(units).items() if k != "fan_in"), "tokens": (r or {}).get("tokens", 0),
            "attempt": attempt, "warnings": [w[:300] for w in warns[:8]], "types": [u.get("type") for u in units]})
    log(plan_summary(units))

class _PlanNotWritten(ValueError):
    pass


def get_plan(replan=None, old_plan=None):
    """Planner call(s) + validation; an invalid plan goes back with the error list (PLAN_REWRITES times, PLAN_TOTAL_S in total). The last
    attempt accepts the planning contract's soft errors as warnings. A dead backend -> None (infra). No valid first plan -> a minimal plan."""
    t_begin = time.time()
    if replan:
        old = [u for u in (old_plan or []) if isinstance(u, dict)]
        x = replan["uid"]
        txt = read(os.path.join(unit_dir(x), "residual.md"), "").strip() or read(os.path.join(unit_dir(x), "critic_report.md"), "(no residual.md / critic_report.md)").strip()
        done = [u["id"] for u in old if u.get("status") == "done"]
        base = REPLAN_PROMPT.format(uid=x, reason=replan.get("reason", "failed"), blocked=", ".join(replan.get("blocked") or []) or "(none)",
                                    status_table=unit_status_table(), residual=txt[:6000] + ("\n[...truncated - read the file]" if len(txt) > 6000 else ""),
                                    done_block="\n".join("  %s -> /workspace/%s/ : %s" % (d, d, _handoff_summary(d)) for d in done) or "  (none)",
                                    retired=", ".join(u["id"] for u in old if u.get("status") in HISTORY) or "(none)") + notes_block("planner_notes", PLANNER_NOTES_TITLE)
        total = min(PLAN_TOTAL_S, 1800)
    else:
        base = (PLAN_PROMPT % {"ncpus": NCPUS, "mem": (MEM_GB if MEM_GB > 0 else "node memory"), "rmin": REPORT_MIN, "maxu": MAX_UNITS}) + notes_block("planner_notes", PLANNER_NOTES_TITLE)
        total = PLAN_TOTAL_S
    prompt, attempt, max_attempts, last_obj, budget, wrap = base, 0, PLAN_REWRITES + 1, None, PLAN_T, (300 if replan else PLAN_WRAP_FIRST_T)
    while attempt < max_attempts:
        attempt += 1
        left = total - (time.time() - t_begin)
        if attempt > 1 and left < 600:
            break
        if replan:
            REPLANNING.set()
        before = _mtime(os.path.join(PD, "plan.json"))
        try:
            with PLANNER_LOCK:
                r = run_call(prompt, int(min(budget, max(600, left))), "replan" if replan else "plan", wrapup=WRAP_PLAN, wrap_t=wrap)
            raw = read(os.path.join(PD, "plan.json"), "null")
        finally:
            REPLANNING.clear()
        if r.get("infra") or INFRA["dead"]:
            ledger({"kind": "plan", "ok": False, "infra": True, "replan_of": replan["uid"] if replan else None})
            return None
        try:
            if _mtime(os.path.join(PD, "plan.json")) in (None, before):   # not (re)written: the file on disk is not its answer
                raise _PlanNotWritten("- /workspace/_pece/plan.json was not written in this attempt")
            obj = json.loads(raw)
            if split_plan(obj)[0]:
                last_obj = obj
            strict = attempt < max_attempts and (total - (time.time() - t_begin)) >= 900
            errs, warns, units, reqs, reads = validate_plan(obj, old_plan=old_plan if replan else None, strict=strict)
            for w in warns:
                log("plan warning: %s" % w)
            if errs:
                raise ValueError("\n".join("- " + e for e in errs))
            _accept_plan(units, reqs, reads, obj, r, attempt, warns, replan)
            if PLAN_ONLY:
                open(os.path.join(PD, "plan_summary.txt"), "w").write(plan_summary(units) + "\nvalidation: OK (attempt %d)%s\n" % (
                    attempt, ("; warnings:\n  " + "\n  ".join(warns)) if warns else ""))
                log("PLAN-ONLY diagnostic: plan written and validated, exiting before execution")
                sys.exit(0)
            return units
        except SystemExit:
            raise
        except Exception as e:
            log("plan.json invalid (attempt %d):\n%s" % (attempt, e))
            ledger({"kind": "plan_invalid", "attempt": attempt, "replan_of": replan["uid"] if replan else None, "errors": str(e)[:1500]})
            if OVERRIDE.is_set():
                break
            if isinstance(e, _PlanNotWritten):   # nothing to edit: a fresh session writes the plan first and refines it after
                prompt = (base + "\n\nThe previous planner session ended WITHOUT writing /workspace/_pece/plan.json. Write it now, before anything "
                          "else: the TASK BOOK items in the header are what will be judged - write a complete plan from them first, read the paper "
                          "only for a method question they leave open, then refine the written file if time remains (attempt %d of %d)."
                          % (attempt + 1, max_attempts))
                budget, wrap = (PLAN_T // 2, 600) if not replan else (PLAN_FIX_T, 300)
            else:
                why = str(e)
                if not (why.startswith("- ") or isinstance(e, json.JSONDecodeError)):   # a Python error inside the check: name the type rules
                    why = ("- the orchestrator could not read a field of plan.json (%s: %s) - a field has the wrong type: a requirement's owner is ONE "
                           "unit id string; a unit's depends_on, deliverables, done_criteria and notes are lists of strings; cores and mem_gb are "
                           "numbers; a reading's check_by is one unit id and its version an integer" % (type(e).__name__, why[:200]))
                prompt = (base + "\n\nYour previous /workspace/_pece/plan.json was REJECTED. The orchestrator's check reported:\n%s\nFix exactly these "
                          "points by EDITING /workspace/_pece/plan.json in place - keep every other unit, requirement and reading as it is, do not plan "
                          "again from scratch (attempt %d of %d)." % (why[:3000], attempt + 1, max_attempts))
                budget, wrap = PLAN_FIX_T, 300   # a fix attempt edits the file: short call, short pens-down
    ledger({"kind": "plan", "ok": False, "replan_of": replan["uid"] if replan else None})
    if replan:
        return None
    if PLAN_ONLY:
        log("PLAN-ONLY diagnostic: no valid plan")
        sys.exit(2)
    if last_obj is not None:
        try:   # best effort: a plan the check cannot even read falls through to the minimal plan, never ends the episode
            fixed = _repair_plan(last_obj)
            if fixed:
                errs, warns, units, reqs, reads = validate_plan(fixed, strict=False)
                if not errs:
                    ledger({"kind": "plan_repaired", "units": [u["id"] for u in units]})
                    log("no plan passed the check -> the last parseable plan, mended, is used")
                    _accept_plan(units, reqs, reads, fixed, None, attempt, warns + ["repaired"], None)
                    return units
        except Exception as e:
            log("mending the last parseable plan failed: %s" % e)
            ledger({"kind": "plan_repair_error", "error": str(e)[:300]})
    units = _minimal_plan()
    ledger({"kind": "plan_minimal", "units": [u["id"] for u in units]})
    log("no parseable plan inside the planning budget -> the minimal plan (one produce unit + render)")
    _accept_plan(units, [], RUN.get("readings") or [], None, None, attempt, ["minimal plan"], None)
    return units

def owned_rows(uid):
    return [r for r in (RUN.get("requirements") or []) if r.get("owner") == uid]

def _rows_text(rows):
    return "\n".join("- %s%s (%s): %s%s" % (r.get("id"), " [CORE]" if r.get("core") else "", r.get("F") or "-", str(r.get("what"))[:300],
                                            (" - precision target: %s" % str(r.get("precision_target"))[:200]) if r.get("precision_target") else "")
                     for r in rows)

def write_spec(u):
    """/workspace/<id>/spec.md - the unit's own brief (rewritten at launch and on every restart)."""
    ud = unit_dir(u["id"])
    os.makedirs(ud, exist_ok=True)
    deps = [d for d in (u.get("depends_on") or [])]
    rows = (RUN.get("requirements") or []) if u.get("type") == "render" else owned_rows(u["id"])
    lines = ["# Unit %s\n" % u["id"], "## Goal\n%s\n" % u["goal"],
             "## Type / resources\ntype: %s; cores: %s; mem_gb: %s; depends_on: %s%s\n"
             % (u.get("type"), u.get("cores"), u.get("mem_gb"), ", ".join(str(x) for x in deps) or "(none)",
                ("; scale_knobs: %s" % json.dumps(u.get("scale_knobs"), ensure_ascii=False)) if u.get("scale_knobs") else ""),
             "## Directory\n/workspace/%s/ - your working directory; code, data, logs, profile.json and handoff.json go here.\n" % u["id"],
             "## Clock\nalloc_min: %s (minutes of wall planned for this unit); t_launch: %d (epoch seconds; the live figures are in "
             "/workspace/_pece/clock.json).\n" % (u.get("alloc_min") if u.get("alloc_min") is not None else "(not set)", int(u.get("t_launch") or time.time())),
             ("## Required rows %s (never optional; the precision target is the error per plotted point the claim needs)\n%s\n"
              % ("of the whole figure - account for every one in report.md" if u.get("type") == "render" else "this unit owns", _rows_text(rows))) if rows else "",
             "## Readings\nUse /workspace/READINGS.md as written (shared by every unit); report evidence against a reading in handoff.json \"reading_issue\".\n",
             ("## Readings this unit settles FIRST (before any production run: run each check on the smallest exact case and write the verdict into "
              "handoff.json \"readings_verdict\": [{\"id\", \"verdict\", \"evidence\": \"<check file>\"}])\n%s\n"
              % "\n".join("- %s: options %s; check: %s" % (x.get("id"), json.dumps(x.get("options") or [], ensure_ascii=False), x.get("check"))
                           for x in (RUN.get("readings") or []) if x.get("check_by") == u["id"])) if any(x.get("check_by") == u["id"] for x in (RUN.get("readings") or [])) else "",
             "## Deliverables\n" + "\n".join("- %s" % d for d in u["deliverables"]),
             "\n## Done criteria\n" + "\n".join("- %s" % c for c in u["done_criteria"]),
             ("\n## Planner notes (numbers without a task-book item - information, not criteria)\n" + "\n".join("- %s" % c for c in (u["notes"] if isinstance(u["notes"], list) else [u["notes"]]))) if u.get("notes") else "",
             "\n## Judged against\nThe TASK BOOK block in every prompt header (CLAUDE.md's judged sections, numbered F1..Fn); the critic audits provenance "
             "(G1), implementation (G2) and the task-book items and required rows this unit serves (G3).",
             "\n## Inputs\n" + ("\n".join("- %s -> /workspace/%s/ (%s): read /workspace/%s/handoff.json first%s%s"
                                           % (d, d, ("DONE WITH GAP" if (unit_by_id(d) or {}).get("gap") else "final" if (unit_by_id(d) or {}).get("status") == "done" else "provisional"), d,
                                              ("; needs: %s" % (u.get("needs") or {}).get(d)) if isinstance(u.get("needs"), dict) and (u.get("needs") or {}).get(d) else "",
                                              (" [GAP: this upstream ended with an unmet item (%s) - its data are real; never fill, rescale or calibrate it]" % (unit_by_id(d) or {}).get("gap_note", "")[:300]) if (unit_by_id(d) or {}).get("gap") else "")
                                           for d in deps) if deps else "(no upstream units)")]
    if u.get("restarts"):
        lines.append("\n## Earlier rounds\n" + "\n".join("- %s/ (residual.md inside)" % a for a in (u.get("archives") or [])))
    with open(os.path.join(ud, "spec.md"), "w") as f:
        f.write("\n".join(x for x in lines if x is not None) + "\n")
    tp = os.path.join(ud, "handoff_template.json")
    if not os.path.exists(tp):
        json.dump({"uid": u["id"], "deliverables": [{"path": d, "what": "<one phrase>"} for d in (u.get("deliverables") or [])],
                   "key_numbers": {"<name>": "<value or 'value (where saved)'>"},
                   "criteria": [{"item": "F<n>", "value": "<measured>", "target": "<the item's number>", "pass": True}],
                   "how_to_use": "<imports, entry points, file formats>", "checks": [{"cmd": "<command run>", "observed": "<actual output>"}],
                   "known_limits": "<anything reduced, approximated or uncertain - or 'none'>", "stopped": None,
                   "_note": "delete this key; add \"waiting\": {\"pid\": <int>, \"done_marker\": \"/workspace/%s/bg.done\", \"expect_min\": <minutes>, \"resume_note\": \"...\"} only while a detached job runs; \"reading_issue\" only with evidence" % u["id"]},
                  open(tp, "w"), indent=1)

def handoff_block(uids, title="UPSTREAM HANDOFFS", limit=5000):
    """The handoff.json of the given units, verbatim (truncated), as one prompt block (the critic's copy of the audited claim)."""
    L = ["%s (%d unit%s; each block is /workspace/<id>/handoff.json verbatim - the FILES it lists are the truth, "
         "the prose is a claim):" % (title, len(uids), "" if len(uids) == 1 else "s")]
    for x in uids:
        txt = read(os.path.join(unit_dir(x), "handoff.json"), "").strip()
        if not txt:
            txt = "(no handoff.json on disk)"
        if len(txt) > limit:
            txt = txt[:limit] + "\n[...truncated - read the file]"
        L.append("--- %s ---\n%s" % (x, txt))
    return "\n".join(L)

# ---------------------------------------------------------------- notes (data, not code) and the residual bank
NOTES_DIR = os.environ.get("RA3SR_NOTES_DIR") or os.path.join(os.path.dirname(os.path.abspath(__file__)), "memories")
NOTES = {}
NOTE_NAMES = ("planner_notes", "critic_notes", "residual_bank", "libraries")


def load_notes():
    """The code carries the mechanics; the lessons live in NOTES_DIR/*.md. Each file present is loaded, copied to
    /workspace/_pece/notes/ for the record and hashed into the ledger; libraries.md is published as /workspace/LIBRARIES.md.
    A file that is absent or empty is left out (the ablation switch), with a warning and a notes_missing ledger event."""
    NOTES.clear()
    rec = {}
    for name in NOTE_NAMES:
        txt = (read(os.path.join(NOTES_DIR, name + ".md"), "") or "").strip()
        NOTES[name] = txt
        rec[name] = ({"bytes": len(txt), "sha": hashlib.sha256(txt.encode("utf-8")).hexdigest()[:8]} if txt else None)
        if txt:
            try:
                os.makedirs(os.path.join(PD, "notes"), exist_ok=True)
                with open(os.path.join(PD, "notes", name + ".md"), "w") as f:
                    f.write(txt + "\n")
            except Exception as e:
                log("notes copy failed (%s): %s" % (name, e))
    if NOTES.get("libraries"):
        try:
            with open(os.path.join(WS, "LIBRARIES.md"), "w") as f:
                f.write(NOTES["libraries"] + "\n")
        except Exception as e:
            log("LIBRARIES.md write failed: %s" % e)
    ledger({"kind": "notes_loaded", "dir": NOTES_DIR, "notes": rec})
    log("notes: %s" % ", ".join("%s %d B" % (k, v["bytes"]) if v else "%s -" % k for k, v in rec.items()))
    missing = [name for name in NOTE_NAMES if not NOTES.get(name)]
    if missing:   # the run goes on without these memories, on the record
        ledger({"kind": "notes_missing", "dir": NOTES_DIR, "missing": missing})
        log("WARNING: memory file(s) absent or empty in %s: %s - the run goes on without them"
            % (NOTES_DIR, ", ".join(name + ".md" for name in missing)))

def notes_block(name, title, index=False):
    """The prompt tail carrying a note ('' when absent); index=True appends the RESIDUAL INDEX (full audits and checkpoints only)."""
    txt = NOTES.get(name) or ""
    out = ("\n\n%s\n%s" % (title, txt)) if txt else ""
    if index:
        out += bank_index_block()
    return out

BANK_K = 3                 # keyword matches per launch
BANK_MAX_CHARS = 4000      # cap of one residual block

_BANK_CACHE = {}

def bank_entries():
    """The residual bank as entries {id, title, stage, event, keys, text}; the older untagged format parses too (keys = title words)."""
    txt = NOTES.get("residual_bank") or ""
    if _BANK_CACHE.get("src") is txt:
        return _BANK_CACHE["entries"]
    clean = re.sub(r"<!--.*?-->", "", txt, flags=re.S)
    out = []
    for m in re.finditer(r"^R(\d+) ([^\n]+)\n(.*?)(?=^R\d+ |\Z)", clean, re.S | re.M):
        rid, title, body = int(m.group(1)), m.group(2).strip(), m.group(3).strip()
        stage, event, keys = set(), set(), []
        t = re.search(r"^TAGS:\s*(.+)$", body, re.M)
        if t:
            for part in t.group(1).split(";"):
                k, _, v = part.partition("=")
                vals = [x.strip().lower() for x in v.split(",") if x.strip()]
                k = k.strip().lower()
                if k == "stage":
                    stage = set(vals)
                elif k == "event":
                    event = set(x for x in vals if x != "none")
                elif k == "keys":
                    keys = vals
        else:
            keys = sorted(set(re.findall(r"[a-z]{5,}", title.lower())))
        body_txt = re.sub(r"^TAGS:.*\n?", "", body, flags=re.M).strip()
        out.append({"id": rid, "title": title, "stage": stage, "event": event, "keys": keys,
                    "text": ("R%d %s\n%s" % (rid, title, body_txt)).strip()})
    _BANK_CACHE.update(src=txt, entries=out)
    return out


def _bank_norm(text):
    return " " + re.sub(r"[^a-z0-9]+", " ", (text or "").lower()) + " "


def bank_pick(text="", stage=None, events=(), ids=(), always=False, k=None, stage_only=None, ids_cap=4, ev_cap=3):
    """Cited IDs first, then entries whose event tag matches, then (launches) the 'always' entries and the best keyword matches."""
    k = BANK_K if k is None else k
    ents = bank_entries()
    by_id = {e["id"]: e for e in ents}
    picked, seen = [], set()
    def add(e):
        if e is not None and e["id"] not in seen:
            picked.append(e)
            seen.add(e["id"])
    for i in list(ids or ())[:ids_cap]:
        add(by_id.get(int(i)))
    if always and not stage_only:   # the 'always' entries right after the cited ones, before events and keywords
        for e in ents:
            if "always" in e["keys"]:
                add(e)
    ev = set(events or ())
    if ev:
        for e in [e for e in ents if e["event"] & ev and e["id"] not in seen][:ev_cap]:
            add(e)
    if stage_only:
        for e in [e for e in ents if stage_only in e["stage"]][:k]:
            add(e)
        return picked
    if text and k > 0:
        norm = _bank_norm(text)
        scored = []
        for e in ents:
            if e["id"] in seen:
                continue
            hits = sum(1 for kw in e["keys"] if kw != "always" and _bank_norm(kw).strip() and _bank_norm(kw) in norm)
            if hits:
                scored.append((hits + (0.5 if (stage and (stage in e["stage"] or "any" in e["stage"])) else 0.0), -e["id"], e))
        for _, _, e in sorted(scored, key=lambda x: (x[0], x[1]), reverse=True)[:k]:
            add(e)
    return picked

def bank_render(entries, title, where, uid=None, extra=None):
    """The residual block (full texts, cited first, capped at BANK_MAX_CHARS) + ledger 'bank_selected' with the IDs actually rendered."""
    out, n, shown = [], 0, []
    for e in entries or []:
        if out and n + len(e["text"]) > BANK_MAX_CHARS:
            continue
        out.append(e["text"])
        shown.append(e["id"])
        n += len(e["text"])
    ev = {"kind": "bank_selected", "unit": uid, "where": where, "ids": shown, "dropped": [e["id"] for e in (entries or []) if e["id"] not in shown]}
    ev.update(extra or {})
    ledger(ev)
    return ("\n\n%s\n%s" % (title, "\n\n".join(out))) if out else ""

def _fix_plan_of(txt):
    """The last FIX_PLAN: {...} JSON of a report text -> dict or None."""
    best = None
    for m in re.finditer(r"FIX_PLAN\s*:\s*(\{.*?\})\s*$", txt or "", re.M):
        try:
            d = json.loads(m.group(1))
            if isinstance(d, dict):
                best = d
        except Exception:
            continue
    return best

def bank_cited_ids(path):
    """The residual-bank IDs a report names in its FIX_PLAN "residual_ids", existing entries only, at most 4. Nothing else in the report is
    read - lattice labels, probe rows and 'checked clear' mentions look like IDs too."""
    txt = read(path, "") or ""
    fp = _fix_plan_of(txt)
    raw = [str(x) for x in fp["residual_ids"]] if (fp and isinstance(fp.get("residual_ids"), list)) else []
    have = {e["id"] for e in bank_entries()}
    ids = []
    for x in re.findall(r"\bR(\d{1,3})\b", " ".join(raw)):
        i = int(x)
        if i in have and i not in ids:
            ids.append(i)
    return ids[:4]

def bank_index_block():
    ents = bank_entries()
    if not ents:
        return ""
    return "\n\n%s\n%s" % (BANK_INDEX_TITLE, "\n".join("R%d %s" % (e["id"], e["title"][:90]) for e in ents))

def bank_start_block(u, restart=None):
    """Residuals for a launch: the 'always' entries + keyword matches; a restart: the IDs the critic cited first, then the restart entries."""
    uid = u["id"]
    try:
        text = json.dumps(u, ensure_ascii=False) + " " + read(os.path.join(unit_dir(uid), "spec.md"), "")[:20000]
    except Exception:
        text = str(u)
    cited = []
    if restart and restart.get("archive"):
        cited = bank_cited_ids(os.path.join(_ws_path(restart["archive"]), "critic_report.md"))
    ents = (bank_pick(text=text, stage="validate", ids=cited, always=True, events=("restart",), k=2, ids_cap=3, ev_cap=1) if restart
            else bank_pick(text=text, stage="validate", always=True))
    return bank_render(ents, BANK_START_TITLE, "restart" if restart else "start", uid, {"cited": cited})

def bank_round_block(uid, events=(), cite=True):
    """Residuals for a fix / continuation / resume round: the critic's RESIDUAL_IDS + the entries tagged with what just happened."""
    cited = bank_cited_ids(os.path.join(unit_dir(uid), "critic_report.md")) if cite else []
    ents = bank_pick(events=set(events or ()), ids=cited, k=0)
    return bank_render(ents, BANK_ROUND_TITLE, "round", uid, {"events": sorted(events or ()), "cited": cited})

def bank_report_block():
    ents = bank_pick(stage_only="report", k=BANK_K)
    return bank_render(ents, BANK_REPORT_TITLE, "report", "report")

def bank_scout_block(uid, archive):
    """The entries the failed round's critic cited + the 'always' entries, for the scouts."""
    cited = bank_cited_ids(os.path.join(_ws_path(archive), "critic_report.md")) if archive else []
    ents = bank_pick(ids=cited, always=True, k=0, ids_cap=3)
    return bank_render(ents, BANK_SCOUT_TITLE, "scout", uid, {"cited": cited})

def mech_events(mech):
    """Bank events of a mechanical failure list."""
    ev = set()
    fails = " ".join(str(x) for x in ((mech or {}).get("fails") or [])).lower()
    if "missing/unparseable deliverable" in fails or "does not exist" in fails:
        ev.add("deliverable_missing")
    if "handoff.json" in fails:
        ev.add("handoff_invalid")
    if "\"waiting\"" in fails or "waiting must" in fails or "waiting\" is a list" in fails:
        ev.add("reg_invalid")
    if (mech or {}).get("outside"):
        ev.add("writes_outside")
    if fails and not ev:
        ev.add("mech")
    return ev

# ---------------------------------------------------------------- critic: full / incremental audits, the checkpoint, verdict parsing
REUSE_MAX_FILES, REUSE_MAX_BYTES = 400, 8 * 2 ** 30
REUSE_SKIP_NAMES = ("handoff.json", "critic_report.md", "residual.md", "mech.json", "spec.md", "profile.json")
REUSE_SKIP_DIRS = ("probes", "__pycache__", ".git", "node_modules", ".dsh_ra3", "site-packages", "dist-packages", ".venv", "venv")

def archive_audit(uid):
    """Move the previous round's critic_report.md (+ probes, residual.md) aside (audit_rN/ in the unit directory) before a re-audit."""
    ud = unit_dir(uid)
    if not os.path.isdir(ud) or not os.path.exists(os.path.join(ud, "critic_report.md")):
        return
    nums = [int(re.sub(r"\D", "", x) or 0) for x in os.listdir(ud) if x.startswith("audit_r")]
    n = 1 + (max(nums) if nums else 0)   # by number, not by count - a foreign audit_rN (copied from an archive by the executor) never collides
    ad = os.path.join(ud, "audit_r%d" % n)
    while os.path.exists(ad):
        n += 1
        ad = os.path.join(ud, "audit_r%d" % n)
    os.makedirs(ad, exist_ok=True)
    for f in ("critic_report.md", "residual.md") + tuple(x for x in os.listdir(ud) if x.startswith("probe_") and x.endswith(".txt")):
        try:
            shutil.move(os.path.join(ud, f), os.path.join(ad, f))
        except OSError:
            pass
    log("archived the previous audit of %s -> audit_r%d" % (uid, n))


def previous_audits_block(uid, limit=6):
    """The earlier audits of this unit (audit_rN/critic_report.md, newest last): grade, FIX LIST head, residual head - so a re-audit
    checks what was asked before instead of rediscovering or silently contradicting it."""
    ud = unit_dir(uid)
    try:
        dirs = sorted([x for x in os.listdir(ud) if x.startswith("audit_r")], key=lambda x: int(re.sub(r"\D", "", x) or 0))
    except Exception:
        dirs = []
    if not dirs:
        return "PREVIOUS AUDITS of this unit: none (first audit)."
    L = ["PREVIOUS AUDITS of this unit (newest last; the files are under /workspace/%s/audit_rN/). First check whether the previous FIX LIST was "
         "carried out; an item you re-raise after it was fixed needs re-verification; if you overturn an earlier ruling, say so explicitly. "
         "A probe from an earlier audit whose inputs are unchanged since (see 'changed since') may be CITED by its audit_rN/ path instead of "
         "re-run - re-run only what changed or what was not covered." % uid]
    for d in dirs[-limit:]:
        rep_ = read(os.path.join(ud, d, "critic_report.md")).strip()
        g = re.match(r"\s*GRADE:\s*(\w)", rep_)
        m = re.search(r"FIX LIST(.*?)(\nFIX_PLAN:|\n#|\Z)", rep_, re.S | re.I)
        fixes = re.sub(r"\s+", " ", m.group(1)).strip()[:600] if m else ""
        res = re.sub(r"\s+", " ", read(os.path.join(ud, d, "residual.md")).strip())[:400]
        try:   # the probes of that audit and whether the unit's files moved since - a cited probe needs unchanged inputs
            probes = sorted(x for x in os.listdir(os.path.join(ud, d)) if x.startswith("probe_") and x.endswith(".txt"))
        except Exception:
            probes = []
        at = _mtime(os.path.join(ud, d, "critic_report.md")) or 0
        ch = _changed_since(ud, at) if at else []
        L.append("- %s: GRADE %s%s%s; probes on disk: %s; unit files changed since: %s" % (
            d, g.group(1) if g else "?", ("; fix list: " + fixes) if fixes else "", ("; residual: " + res) if res else "",
            ", ".join(probes) if probes else "none", ("%d (%s%s)" % (len(ch), ", ".join(ch[:6]), " ..." if len(ch) > 6 else "")) if ch else "none - its probes still apply"))
    return "\n".join(L)


def _changed_since(root, since, limit=4000):
    """Files under root written after `since` (bounded scan; bookkeeping, probes and earlier audits excluded) - tells a re-audit
    whether an earlier probe's inputs moved."""
    out, seen, stack = [], 0, [root]
    while stack and seen < limit and len(out) < 50:
        d = stack.pop()
        try:
            with os.scandir(d) as it:
                for e in it:
                    seen += 1
                    nm = e.name
                    if nm.startswith("audit_r") or nm.startswith("probe_") or nm.startswith(".critic_wait") or nm in REUSE_SKIP_NAMES:
                        continue
                    try:
                        st = e.stat(follow_symlinks=False)
                    except Exception:
                        continue
                    if e.is_dir(follow_symlinks=False):
                        if nm not in REUSE_SKIP_DIRS:
                            stack.append(e.path)
                        continue
                    if st.st_mtime > since:
                        out.append(os.path.relpath(e.path, root))
        except Exception:
            pass
    return sorted(out)


def _pool_facts(uid):
    """What this unit's grant costs the others - for the registration / feasibility rulings (a long job can hold cores that
    ready dependents need)."""
    try:
        g = (POOL.grants.get(uid) if POOL else None) or {}
        uc, um = POOL.used() if POOL else (0, 0)
        plan = RUN.get("plan") or []
        deps = [x.get("id") for x in plan if isinstance(x, dict) and uid in (x.get("depends_on") or []) and x.get("status") not in ("running",) + TERMINAL]
        blocked = [x.get("id") for x in plan if isinstance(x, dict) and x.get("ready_since") and x.get("status") not in ("running",) + TERMINAL]
        return ("; this unit holds %sc/%sGB of the node's %dc (%dc/%dGB granted in total); units waiting for it: %s; ready units blocked by the pool: %s"
                % (g.get("cores", "?"), g.get("mem_gb", "?"), NCPUS, uc, um, ", ".join(deps) or "none", ", ".join(blocked) or "none"))
    except Exception:
        return ""


def unit_activity_text(uid):
    try:
        lv = reap_leftovers(uid, dry=True)
    except Exception:
        lv = []
    try:
        age = time.time() - _dir_activity(unit_dir(uid), 0)
        age_s = "%d min ago" % (age // 60) if age < 1e9 else "unknown"
    except Exception:
        age_s = "unknown"
    return "%d live process(es) of this unit%s; newest file under /workspace/%s/ written %s" % (
        len(lv), (": " + "; ".join(c for _, _, c in lv[:4])[:300]) if lv else "", uid, age_s) + _pool_facts(uid)


def machine_critic(uid, mech, grade="B"):
    """The orchestrator's own report is a FALLBACK (override, or no critic answer twice) and it never grades C: the mechanical findings
    become a B FIX LIST for the executor's own session."""
    archive_audit(uid)
    steps = mech.get("fails") or ["mechanical check failed"]
    hint = ""
    txt = ("GRADE: %s\nGATES: G1=n/a G2=n/a G3=n/a\nMECHANICAL FINDINGS (written by the orchestrator from its "
           "machine check); nothing here is a judgement on the science.\nFIX LIST\n%s\n%s%s"
           "FIX_PLAN: %s\n" % (grade, "\n".join("- " + s for s in steps), hint, mech_notes(mech),
                                json.dumps({"est_min": 10, "steps": steps[:8]}, ensure_ascii=False)))
    try:
        open(os.path.join(unit_dir(uid), "critic_report.md"), "w").write(txt)
    except Exception as e:
        log("machine report write failed for %s: %s" % (uid, e))
    ledger({"kind": "critic", "unit": uid, "grade": grade, "by": "mech", "tokens": 0, "dur": 0,
            "fails": steps[:8], "gates": None, "fix_plan": {"est_min": 10}})
    log("%s: mechanical findings written by the orchestrator as a %s fix list" % (uid, grade))
    return grade


def parse_fix_plan(uid):
    """Last `FIX_PLAN: {...}` JSON line of critic_report.md -> dict (est_min float|None, steps) or None."""
    best = None
    for m in re.finditer(r"FIX_PLAN\s*:\s*(\{.*?\})\s*$", read(os.path.join(unit_dir(uid), "critic_report.md")), re.M):
        try:
            best = json.loads(m.group(1)) if isinstance(json.loads(m.group(1)), dict) else best
        except Exception:
            continue
    if best is None:
        return None
    try:
        v = float(best.get("est_min"))
        best["est_min"] = max(0.0, v) if math.isfinite(v) else None   # inf / NaN are no estimate
    except Exception:
        best["est_min"] = None
    return best


def parse_gates(uid):
    """{G1, G2, G3: pass|hit|None} from the mandatory line-2 `GATES:` of critic_report.md (information for the ledger)."""
    txt = read(os.path.join(unit_dir(uid), "critic_report.md"))
    res = {"G1": None, "G2": None, "G3": None}
    m = re.search(r"^GATES?\s*:\s*(.+)$", txt[:1500], re.M | re.I)
    if m:
        for g, v in re.findall(r"(G[123])\s*[=:]\s*([A-Za-z/]+)", m.group(1)):   # synonyms read, n/a / pending stay None
            v = v.lower()
            res[g.upper()] = "pass" if v in ("pass", "passed", "ok", "met") else ("hit" if v in ("hit", "fail", "failed", "miss", "missed", "partial", "violated") else None)
    return res


def parse_grade(uid):
    head = read(os.path.join(unit_dir(uid), "critic_report.md"))[:200]
    m = re.match(r"\s*GRADE:\s*([ABCDW])\s*(?:\r?\n|$)", head)   # W = a checkpoint's "on track"; a literal echo of "GRADE: A|B|C|D" does not parse
    return m.group(1) if m else None

def parse_reading_change(uid):
    """A report's reading change -> [(id, reading, evidence)] from its FIX_PLAN "reading_change". A change without an existing evidence file (the
    check that decides it) is not a change."""
    txt = read(os.path.join(unit_dir(uid), "critic_report.md"))
    out = []
    fp = _fix_plan_of(txt)
    rc = (fp or {}).get("reading_change")
    if isinstance(rc, dict):
        out.append((str(rc.get("id") or "").strip().upper(), str(rc.get("reading") or "").strip()[:600], str(rc.get("evidence") or "").strip()[:300]))
    good = []
    for k, rd, evd in out:
        if not re.match(r"^K\d+$", k) or not rd:
            continue
        if not _evidence_exists(uid, evd):
            ledger({"kind": "reading_change_rejected", "unit": uid, "id": k, "why": "no evidence file", "evidence": evd[:200]})
            continue
        good.append((k, rd, evd))
    return good

def _evidence_exists(uid, ev, base=None):
    """The evidence names a file that exists (absolute /workspace path, or relative to `base` / the unit directory / its probes)."""
    toks = re.findall(r"/workspace/[^\s,;'\")\]]+", ev or "") + re.findall(r"(?<![\w/])[\w][\w./-]*\.(?:txt|json|npz|npy|csv|log|md|dat|py|png)\b", ev or "")
    for t in toks:
        t = t.rstrip(".,;:")
        for cand in ([_ws_path(t)] if t.startswith("/") else [os.path.join(b, t) for b in ([base] if base else []) + [unit_dir(uid), os.path.join(unit_dir(uid), "probes"), WS]]):
            if os.path.exists(cand):
                return True
    return False

def _anchor_missed(txt):
    """Rows of the report's ANCHORS table whose verdict says missed (quoted in a gap note)."""
    m = re.search(r"\n\s*(?:#+\s*)?ANCHORS\b(.*?)(?=\n\s*(?:#+\s*)?(?:GRADES|GATE CHECK|CRITERIA|FIX LIST|EVIDENCE|WHAT IS WRONG|RESIDUAL)\b|\nFIX_PLAN:|\Z)", txt, re.S | re.I)
    if not m:
        return []
    out = []
    for l in m.group(1).splitlines():
        if l.count("|") < 3 or re.match(r"^\s*\|?\s*:?-{2,}", l) or re.search(r"\bquantity\b.*\bpaper\b", l, re.I):
            continue
        cells = [c.strip() for c in l.strip().strip("|").split("|")]
        verdict = " ".join(cells[4:]) if len(cells) >= 5 else cells[-1]
        if re.search(r"conflict", verdict, re.I):
            continue
        if re.search(r"\b(miss(ed)?|fail(ed|s)?|off|outside|beyond|violat\w*|revers\w*|absent|not met)\b", verdict, re.I):
            out.append(l.strip()[:200])
    return out

def _critic_format_retry(uid, csid, tag, what="report"):
    """A critic session that ended without a graded report gets one short pens-down call."""
    return run_call("You have not delivered a valid graded %s. Write /workspace/%s/critic_report.md NOW: line 1 exactly 'GRADE: A|B|C|D' (a checkpoint "
                    "may also write 'GRADE: W') on what you actually verified - B listing the unverified checks when time ran out, C only for a "
                    "verified defect (with residual.md); line 2 the GATES line; last line FIX_PLAN: {\"est_min\": N, \"steps\": [...], \"residual_ids\": [...], \"reading_change\": null}. Then stop." % (what, uid),
                    slot(900), tag, resume_sid=csid, cwd=unit_dir(uid))

def run_critic(uid, delta=False, notice="", why_delta="", force=False):
    """A full audit, or (delta) an incremental re-audit of a B fix / of a change notice. Returns the grade (A/B/C/D, W read as B) or None under
    the override. Every LLM verdict resets the unit's checkpoint clock."""
    ud = unit_dir(uid)
    if OVERRIDE.is_set() and not force:
        ledger({"kind": "critic_skipped", "unit": uid, "reason": "override"})
        return None
    u = unit_by_id(uid) or {"id": uid}
    fixes_prev = extract_fixes(uid)[:3000] if delta else ""
    at_prev = (_mtime(os.path.join(ud, "critic_report.md")) or 0) if delta else 0
    archive_audit(uid)
    changed, prev_dir = [], ""
    if delta:
        try:
            ds = sorted([x for x in os.listdir(ud) if x.startswith("audit_r")], key=lambda x: int(re.sub(r"\D", "", x) or 0))
            prev_dir = ds[-1] if ds else ""
        except Exception:
            prev_dir = ""
        changed = _changed_since(ud, at_prev) if at_prev else []
    t_c0 = time.time()
    notice = notice or change_notice(u)
    if delta:
        items = (notice or "(no change notice)") if why_delta else ((fixes_prev or "(the previous report had no FIX LIST)") + (("\n" + notice) if notice else ""))
        prompt = (CRITIC_DELTA_PROMPT.format(uid=uid, why=why_delta or "your previous audit graded it B and the executor applied the FIX LIST below.",
                                             prev_dir=prev_dir or "audit_r?", fixes=items,
                                             changed=((", ".join(changed[:40]) + (" ..." if len(changed) > 40 else "")) if changed else "none"),
                                             handoff=handoff_block([uid], title="HANDOFF OF THE AUDITED UNIT"), mech=mech_block(uid), tool_min=CRITIC_TOOL_S // 60)
                  + (CRITIC_RULES + CRITIC_CONTRACT).format(uid=uid) + notes_block("critic_notes", CRITIC_NOTES_TITLE, index=True))
        t_lim, tag = CRITIC_DELTA_T, "criticd_%s" % uid
        ledger({"kind": "critic_delta", "unit": uid, "prev": prev_dir, "changed": len(changed), "notice": bool(notice)})
    else:
        prompt = (CRITIC_PROMPT.format(uid=uid, handoff=handoff_block([uid], title="HANDOFF OF THE AUDITED UNIT"), mech=mech_block(uid),
                                       changes=notice, previous=previous_audits_block(uid), tool_min=CRITIC_TOOL_S // 60)
                  + notes_block("critic_notes", CRITIC_NOTES_TITLE, index=True))
        t_lim, tag = CRITIC_T, "critic_%s" % uid
    r = run_call(prompt, t_lim, tag, wrapup=WRAP_CRITIC.format(uid=uid), cwd=ud)
    csid, tokens = r["sid"], r["tokens"]
    grade = parse_grade(uid)
    if grade is None and (force or not OVERRIDE.is_set()) and not INFRA["dead"] and (csid or os.path.exists(os.path.join(ud, "critic_report.md"))):
        f = _critic_format_retry(uid, csid, "criticfmt_%s" % uid)
        tokens += f["tokens"]
        grade = parse_grade(uid)
    reap_critic(uid, tag, "criticfmt_%s" % uid)
    gates = parse_gates(uid) if grade else None
    if grade == "W":
        grade = "B"   # the audit follows a handoff; "still running" is a fix list ("finish and hand off")
    if grade == "B" and gates and gates.get("G1") == "hit":
        grade = "C"   # a fabricated or untraceable number is never a same-session patch
    rep_ = read(os.path.join(ud, "critic_report.md"))[:12000]
    if grade == "D" and not (re.search(r"\bF\d+\b", rep_) and re.search(r"\((a|b)\)", rep_)):
        ledger({"kind": "d_rejected", "unit": uid, "why": "no (a)/(b) ground with task-book item numbers"})
        grade = "C"
    if grade in ("C", "D"):
        ensure_residual(uid, "grade %s" % grade)
    fp = parse_fix_plan(uid) if grade else None
    ledger({"kind": "critic", "unit": uid, "grade": grade, "by": "delta" if delta else "llm", "tokens": tokens, "dur": int(time.time() - t_c0),
            "gates": gates, "delta": bool(delta), "residual": os.path.isfile(os.path.join(ud, "residual.md")),
            "fix_plan": ({"est_min": fp.get("est_min")} if fp else None), "residual_ids": bank_cited_ids(os.path.join(ud, "critic_report.md")),
            "override": OVERRIDE.is_set()})
    if grade and u.get("type") == "produce":
        LAST_LOOK[uid] = time.time()
        if u.get("inputs") is not None:
            record_inputs(u)   # the audit saw the change notice: the inputs as they are now are the new baseline
        for k, rd, evd in parse_reading_change(uid):
            apply_reading_change(k, rd, evd, uid, "critic")
    return grade

def run_checkpoint(uid, u, reason, job=None):
    """The one time check: STATE, RESULTS SO FAR, PACE, SCALE -> W (on track) / B (named changes, the executor resumes) / C / D. Nothing is
    killed. No verdict -> W while a job runs, else a machine B. Resets the unit's checkpoint clock."""
    ud = unit_dir(uid)
    if OVERRIDE.is_set():
        return "W"
    archive_audit(uid)
    t_c0 = time.time()
    since = time.time() - LAST_LOOK.get(uid, T0)
    ul = usable_left()
    if reason == "after_job":
        sit = ("The unit's job ended and the session that verifies it was cut before it handed off: its results are on disk - look at what is "
               "complete now.")
    elif reason == "past_end":
        t_end = float(job.get("t0") or time.time()) + float(job.get("expect_min") or 0) * 60
        sit = ("The unit registered a job (pid %s) declared at %.0f min; it would end at %s, after the usable end %s: rule whether it can deliver "
               "the required rows in time and what must change." % (job.get("pid"), float(job.get("expect_min") or 0), time.strftime("%H:%M", time.localtime(t_end)),
                                                                   time.strftime("%H:%M", time.localtime(time.time() + ul))))
    else:
        sit = ("The unit has worked %.1f h since its last review (launch, restart or audit)%s." % (since / 3600.0,
               ("; its job (pid %s) is running" % job.get("pid")) if job else "; its executor session was cut at a slice boundary without a handoff"))
    sit += " Usable wall left: %d min." % int(ul // 60)
    notice = change_notice(u)
    prompt = (CHECKPOINT_PROMPT.format(uid=uid, situation=sit + (("\n" + notice) if notice else ""), activity=unit_activity_text(uid),
                                       mech=mech_block(uid) if os.path.exists(os.path.join(ud, "mech.json")) else "MECH CHECK: none yet (no handoff).",
                                       previous=previous_audits_block(uid), usable_end=time.strftime("%H:%M", time.localtime(time.time() + ul)))
              + notes_block("critic_notes", CRITIC_NOTES_TITLE, index=True))
    ledger({"kind": "checkpoint", "unit": uid, "reason": reason, "since_s": int(since), "usable_s": int(ul),
            "job_pid": (job or {}).get("pid"), "implicit": bool((job or {}).get("implicit"))})
    log("%s: CHECKPOINT (%s) - %.1f h since the last look, %d min usable -> the critic reads state, results so far and pace" % (uid, reason, since / 3600.0, ul // 60))
    tag = "criticcp_%s" % uid
    r = run_call(prompt, CHECK_T, tag, wrapup=WRAP_CHECK.format(uid=uid), cwd=ud, wrap_t=(300 if usable_left() < 2400 else 900))
    csid, tokens = r["sid"], r["tokens"]
    grade = parse_grade(uid)
    if grade is None and not OVERRIDE.is_set() and not INFRA["dead"] and (csid or os.path.exists(os.path.join(ud, "critic_report.md"))):
        f = _critic_format_retry(uid, csid, "criticfmt_%s" % uid, "checkpoint")
        tokens += f["tokens"]
        grade = parse_grade(uid)
    reap_critic(uid, tag, "criticfmt_%s" % uid)
    if grade == "A":
        grade = "W"
    if grade is None:
        ledger({"kind": "checkpoint_no_verdict", "unit": uid, "tokens": tokens})
        grade = "W" if job else machine_critic(uid, {"fails": ["the checkpoint gave no verdict: finish the work, then write handoff.json"]}, "B")
    if grade in ("C", "D"):
        ensure_residual(uid, "checkpoint: grade %s" % grade)
    fp = parse_fix_plan(uid)
    ledger({"kind": "critic", "unit": uid, "grade": grade, "by": "checkpoint", "reason": reason, "tokens": tokens, "dur": int(time.time() - t_c0),
            "gates": None, "fix_plan": ({"est_min": fp.get("est_min")} if fp else None), "residual_ids": bank_cited_ids(os.path.join(ud, "critic_report.md")),
            "override": OVERRIDE.is_set()})
    log("%s: checkpoint ruling %s (est %s min)" % (uid, grade, (fp or {}).get("est_min")))
    LAST_LOOK[uid] = time.time()
    CP_DONE.setdefault(uid, set()).add((_job_key(job), reason))
    if u.get("inputs") is not None:
        record_inputs(u)
    return grade

def _job_key(job):
    return (int((job or {}).get("pid") or 0), str((job or {}).get("done_marker") or "")) if job else None

def checkpoint_due(uid, job=None, t_now=None):
    """The one time check -> the reason it is due now, or None: 'past_end' (a registered job declared past the usable end, once per job) or
    'interval' (CP_S since the unit's last look, in any state, implicit jobs included). Never under the override or in the last LAST_ACT_S.
    (A session cut right after its job ended is looked at too - the unit worker asks for that 'after_job' checkpoint itself.)"""
    if not uid or OVERRIDE.is_set() or usable_left() < LAST_ACT_S:
        return None
    t_now = t_now or time.time()
    done = CP_DONE.get(uid) or set()
    if job and not job.get("implicit"):
        key = _job_key(job)
        if float(job.get("t0") or t_now) + float(job.get("expect_min") or 0) * 60 > t_now + usable_left() and (key, "past_end") not in done:
            return "past_end"
    if uid in LAST_LOOK and t_now - LAST_LOOK[uid] >= CP_S:
        return "interval"
    return None

# ---------------------------------------------------------------- archives, residuals, restarts and what a fresh attempt may reuse

def archive_dir(uid, suffix, reason):
    """Move /workspace/<uid>/ aside as /workspace/<uid>.<suffix>/ - a readable reference that is never touched again."""
    src = unit_dir(uid)
    if not os.path.isdir(src):
        return None
    dst, n = src + "." + suffix, 0
    while os.path.exists(dst):   # never overwrite an earlier archive
        n += 1
        dst = "%s.%s_%d" % (src, suffix, n)
    shutil.move(src, dst)
    ledger({"kind": "archive", "unit": uid, "dir": _ws_name(dst), "reason": reason})
    log("%s: directory archived -> %s (%s)" % (uid, _ws_name(dst), reason))
    return dst


def ensure_residual(uid, reason):
    """residual.md in the unit directory: the critic writes it on C / D; when it is missing the orchestrator writes one from
    critic_report.md and mech.json, so the next attempt always has one. Returns who wrote it ("critic" or "orchestrator")."""
    ud = unit_dir(uid)
    p = os.path.join(ud, "residual.md")
    if os.path.isfile(p) and read(p).strip():
        return "critic"
    crit, fails = read(os.path.join(ud, "critic_report.md")).strip(), []
    try:
        fails = json.load(open(os.path.join(ud, "mech.json"))).get("fails") or []
        fails = [str(f) for f in fails] if isinstance(fails, list) else []   # mech.json can be an agent's rewrite
    except Exception:
        pass
    os.makedirs(ud, exist_ok=True)
    open(p, "w").write("# residual of unit %s (written by the ORCHESTRATOR: the critic left no residual.md)\nREASON: %s\n%s%s"
                       % (uid, reason, ("MECHANICAL CHECK FAILURES:\n%s\n" % "\n".join("- " + f for f in fails)) if fails else "",
                          ("\nCRITIC REPORT (verbatim):\n%s\n" % crit[:8000]) if crit else "(no critic report on disk)\n"))
    return "orchestrator"


def extract_fixes(uid):
    txt = read(os.path.join(unit_dir(uid), "critic_report.md"))
    starts = [m.start() for m in re.finditer(r"FIX LIST", txt, re.I)
              if not re.search(r"previous\W*$", txt[max(0, m.start() - 12):m.start()], re.I)]   # skip "PREVIOUS FIX LIST ..." echoes of a re-audit
    m = re.search(r"FIX LIST(.*?)(\n#|\nFIX_PLAN:|\Z)", txt[starts[0]:], re.S | re.I) if starts else None
    return (m.group(1).strip() if m else txt[-3000:])


def reusable_paths(residual_txt):
    """The paths named in residual.md's REUSABLE section (header line remainder + following lines, up to the next SIGNATURE / PROBE /
    SUGGESTION / NOT REUSABLE / FIX_PLAN header). Absolute /workspace/<id>/... tokens and the first path-like token of a bullet line count."""
    m = re.search(r"^[ \t#*>-]*REUSABLE\b[ \t]*:?(.*)\n?((?:(?![ \t#*>-]*(?:NOT REUSABLE|SIGNATURE|PROBE|SUGGESTION|FIX_PLAN)\b).*\n?)*)", residual_txt, re.M | re.I)
    if not m:
        return []
    head = re.split(r"NOT REUSABLE", m.group(1), flags=re.I)[0]
    out = []
    for line in [head] + m.group(2).splitlines():
        toks = re.findall(r"/workspace/[\w.-]+/[^\s`'\",;:)\]]+", line)
        if not toks:
            mm = re.match(r"^[ \t*>-]*`?([\w][\w./\-]*)", line)
            if mm and ("/" in mm.group(1) or "." in mm.group(1)) and not mm.group(1).lower().startswith(("none", "n/a", "nothing")):
                toks = [mm.group(1)]
        for t in toks:
            t = t.rstrip(".,;:")
            if t and t not in out:
                out.append(t)
    return out


def copy_reusable(uid, arch):
    """Copy the files the critic listed under REUSABLE in the archived residual.md into the fresh unit directory - regular files under
    the unit only, REAL copies (never links: the archive stays untouched), bounded in count and bytes; bookkeeping files and probes never.
    Returns the relative paths copied (ledger: reusable_copied)."""
    if not arch or not os.path.isdir(arch):
        return []
    txt = read(os.path.join(arch, "residual.md"), "")
    if not txt.strip():
        return []
    return _copy_from_archive(uid, arch, reusable_paths(txt), "residual REUSABLE")


def _copy_from_archive(uid, arch, toks, source):
    """The copy machinery of copy_reusable for any list of unit paths (`source` names who vouched for them: the critic's REUSABLE list,
    or the declared deliverables of a B round whose gates all passed - an anchor restart)."""
    if not arch or not os.path.isdir(arch):
        return []
    ud, prefix = unit_dir(uid), "/workspace/%s/" % uid
    arch_real, copied, skipped, total = os.path.realpath(arch), [], [], 0
    for tok in toks:
        rel = tok[len(prefix):] if tok.startswith(prefix) else (tok if not tok.startswith("/") else None)
        if rel is None:
            skipped.append(tok + " (outside the unit)"); continue
        rel = os.path.normpath(rel)
        if rel.startswith("..") or rel in (".", ""):
            skipped.append(tok + " (outside the unit)"); continue
        src = os.path.join(arch, rel)
        if not os.path.exists(src):
            skipped.append(rel + " (not in the archive)"); continue
        files = []
        if os.path.isdir(src) and not os.path.islink(src):
            for dp, dns, fns in os.walk(src):
                dns[:] = [d for d in dns if d not in REUSE_SKIP_DIRS and not d.startswith("audit_r")]
                for fn in fns:
                    files.append(os.path.join(dp, fn))
        else:
            files = [src]
        for f in files:
            r = os.path.relpath(f, arch)
            nm = os.path.basename(f)
            if nm in REUSE_SKIP_NAMES or (nm.startswith("probe_") and nm.endswith(".txt")) or r.split(os.sep)[0] in REUSE_SKIP_DIRS or r.startswith("audit_r"):
                skipped.append(r + " (bookkeeping)"); continue
            if os.path.islink(f) or not os.path.isfile(f) or not os.path.realpath(f).startswith(arch_real + os.sep):
                skipped.append(r + " (not a regular file)"); continue
            try:
                sz = os.path.getsize(f)
            except OSError:
                continue
            if len(copied) >= REUSE_MAX_FILES or total + sz > REUSE_MAX_BYTES:
                skipped.append(r + " (over the copy bound)"); continue
            dst = os.path.join(ud, r)
            try:
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copy2(f, dst)
                copied.append(r); total += sz
            except Exception as e:
                skipped.append("%s (%s)" % (r, e))
    ledger({"kind": "reusable_copied", "unit": uid, "archive": _ws_name(arch), "n": len(copied), "bytes": total, "files": copied[:60],
            "skipped": skipped[:30], "source": source})
    if copied or skipped:
        log("%s: %s from %s -> %d file(s) (%.1f MB) copied into the fresh directory%s" % (uid, source, _ws_name(arch), len(copied), total / 1e6,
            ("; skipped: " + "; ".join(skipped[:5])) if skipped else ""))
    return copied

def _copy_code_from_archive(uid, arch, cap_files=400, cap_bytes=50 * 1024 * 1024):
    """The archived round's CODE files (source, scripts, configs, requirements; never data, logs, bookkeeping, audits, probes or vendored
    packages) copied into the fresh directory where nothing exists yet (the REUSABLE copies come first)."""
    if not arch or not os.path.isdir(arch):
        return []
    ud, copied, total = unit_dir(uid), [], 0
    skip_names = {"handoff.json", "critic_report.md", "residual.md", "mech.json", "spec.md", "STATUS.md", "bg.pid", "profile.json"}
    for dp, dns, fns in os.walk(arch):
        dns[:] = sorted(d for d in dns if d not in REUSE_SKIP_DIRS and not d.startswith("audit_r") and d not in ("logs", "from_scout", "from_scout_also")
                        and not any(x.endswith((".dist-info", ".egg-info")) for x in dns))
        for fn in sorted(fns):
            if fn in skip_names or fn.startswith("probe_") or fn.endswith(".log"):
                continue
            low = fn.lower()
            if not (low.endswith(CODE_EXT) and (not low.endswith(".txt") or "requirement" in low or low == "cmakelists.txt")):
                continue
            src = os.path.join(dp, fn)
            rel = os.path.relpath(src, arch)
            dst = os.path.join(ud, rel)
            try:
                if os.path.islink(src) or not os.path.isfile(src) or os.path.exists(dst) or _vendored(src, arch):
                    continue
                sz = os.path.getsize(src)
                if sz > 2 * 1024 * 1024 or total + sz > cap_bytes or len(copied) >= cap_files:
                    continue
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copy2(src, dst)
                copied.append(rel); total += sz
            except Exception as e:
                log("code copy %s failed: %s" % (rel, e))
    if copied:
        ledger({"kind": "code_copied", "unit": uid, "archive": _ws_name(arch), "n": len(copied), "bytes": total, "files": copied[:60]})
        log("%s: %d code file(s) of the archived round copied back as the starting point (%d bytes)" % (uid, len(copied), total))
    return copied


def _produce_downstream(uid):
    return [d for d in downstream_ids(uid, RUN["plan"]) if (unit_by_id(d) or {}).get("type") != "render"]

def _prov_restart(u, rounds, g):
    """A unit whose files dependents may already use is restarted -> its deliverables come back into the fresh directory."""
    if not u.get("released_deps"):
        return False, ""
    ledger({"kind": "provisional_restart", "unit": u["id"], "round": rounds, "grade": g, "dependents": _produce_downstream(u["id"])})
    return True, PROV_RESTART_NOTE


def restart_unit(u, rounds, grade, note="", keep_deliverables=False):
    """A fresh attempt: the unit's processes stopped, residual.md guaranteed, the directory archived as /workspace/<id>.r<n>/, a fresh
    directory with spec.md, the critic-verified files (REUSABLE) and the previous code copied back; keep_deliverables (dependents already use
    the files) copies the archived deliverables back too. Returns the restart record for the new session."""
    uid = u["id"]
    try:
        w_old = _waiting_of(uid)
        kp = (w_old or {}).get("pid")
        killed = reap_leftovers(uid, kill_pid=(kp if kp and _pid_is_units(kp, uid) else None))
        if killed:
            ledger({"kind": "restart_reaped", "unit": uid, "n": len(killed)})
    except Exception as e:
        log("%s: reaping the archived round's processes failed: %s" % (uid, e))
    by = ensure_residual(uid, "grade %s (round %d)" % (grade, rounds))
    n = int(u.get("restarts") or 0) + 1
    arch = archive_dir(uid, "r%d" % n, "restart after grade %s" % grade)
    b = u.get("_best") or {}
    if arch and b.get("round") == n - 1:   # the best validated round is the one just archived
        b["dir"] = _ws_name(arch)
    u["restarts"] = n
    u.setdefault("archives", []).append(_ws_name(arch) if arch else "(no directory)")
    write_spec(u)
    u.pop("handoff_valid_at", None)   # the fresh attempt has no valid handoff yet (the file gate must not open on archived copies)
    copied = copy_reusable(uid, arch) if by == "critic" else []
    kept = []
    if arch and keep_deliverables:
        kept = [x for x in _copy_from_archive(uid, arch, [d for d in (u.get("deliverables") or []) if isinstance(d, str)], "deliverables of the archived round") if x not in copied]
    code = _copy_code_from_archive(uid, arch) if (RESTART_KEEP_CODE and arch) else []
    ledger({"kind": "restart", "unit": uid, "round": rounds, "n": n, "grade": grade, "archive": _ws_name(arch) if arch else None, "residual_by": by,
            "reusable": len(copied), "kept": len(kept), "code": len(code)})
    log("%s RESTART %d: archive %s, residual.md by the %s, fresh directory%s" % (uid, n, _ws_name(arch) if arch else "-", by,
        (", %d verified file(s) copied back" % len(copied)) if copied else ""))
    LAST_LOOK[uid] = time.time()
    return {"grade": grade, "archive": _ws_name(arch) if arch else "/workspace/%s (no archive)" % uid, "round": n, "note": note, "copied": copied,
            "kept": kept, "code": code}

def _scale_hint(u):
    """Knobs a bounded redo must use: the unit's own measured scale_knobs (profile.json, current directory or the newest archive) and the planner's."""
    pj = None
    for p in [os.path.join(unit_dir(u["id"]), "profile.json")] + [os.path.join(_ws_path(a), "profile.json") for a in reversed(u.get("archives") or [])]:
        try:
            pj = json.load(open(p))
            if isinstance(pj, dict):   # an agent's profile.json in another shape is skipped
                break
            pj = None
        except Exception:
            pass
    return ("SCALE KNOBS (lower PRECISION first - never drop a required size, value or series while a precision knob can still be lowered; re-time ONE "
            "unit of work, then produce the full required set; keep every task-book item decidable and "
            "document the reduction under known_limits): measured scale_knobs=%s; planner-declared scale_knobs=%s."
            % (json.dumps(((pj or {}).get("scale_knobs") or []), ensure_ascii=False)[:400],
               json.dumps(u.get("scale_knobs") or [], ensure_ascii=False)[:400]))

# ---------------------------------------------------------------- C-grade SCOUTING: parallel root-cause candidates with proofs of concept, a panel picks
SCOUT_K = 3                                           # scouts per round
SCOUT_T = _envi("RA3_SCOUT_T", 2700)                  # one scout's session
SCOUT_POC_MIN = 30                                    # its proof-of-concept computation (minutes)
SCOUT_SELECT_T = _envi("RA3_SCOUT_SELECT_T", 1800)    # one selection critic
SCOUT_PANEL = 3                                       # selection critics (Borda)
SCOUT_WRAP_T = 300                                    # the pens-down of a scout / a selection critic (no 30-min wrap-ups inside the scouting)
SCOUT_NEED_S = SCOUT_T + SCOUT_SELECT_T + 2 * SCOUT_WRAP_T + MIN_ATTEMPT_S + 600   # usable wall a scouted fresh attempt needs
SCOUT_COPY_MAX_B = 50 * 1024 * 1024


def scouting_due(u):
    """A C is scouted whenever a scouted fresh attempt still fits the usable wall (no count cap)."""
    return not OVERRIDE.is_set() and not INFRA["dead"] and usable_left() >= SCOUT_NEED_S

def _read_candidate(sdir):
    """candidate.json of a scout directory -> dict (hypothesis + poc required) or None."""
    try:
        c = json.loads(read(os.path.join(sdir, "candidate.json"), "null"))
    except Exception:
        return None
    if not isinstance(c, dict) or not str(c.get("hypothesis") or "").strip() or not isinstance(c.get("poc"), dict):
        return None
    s = c.get("supports")
    c["supports"] = s is True or str(s).strip().lower() in ("true", "yes", "1")
    rc = c.get("reading_change")
    c["reading_change"] = rc if (isinstance(rc, dict) and re.match(r"^K\d+$", str(rc.get("id") or "").strip()) and str(rc.get("reading") or "").strip()) else None
    return c

def _parse_rank(txt, valid):
    """'RANK: 2 3 1' -> [2, 3, 1]; 'RANK: NONE' -> 'NONE'; no RANK line -> None. Also returns the ADOPT and DISQUALIFIED lists (valid scout numbers)."""
    head = (txt or "")[:800]
    m = re.search(r"^\s*RANK\s*:\s*(.+)$", head, re.M | re.I)
    def nums(rx):
        mm = re.search(rx, head, re.M | re.I)
        got = [int(x) for x in re.findall(r"\d+", mm.group(1))] if mm and not re.match(r"\s*none\b", mm.group(1), re.I) else []
        return [k for i, k in enumerate(got) if k in valid and k not in got[:i]]
    adopt, disq = nums(r"^\s*ADOPT\s*:\s*(.+)$"), nums(r"^\s*DISQUALIFIED\s*:\s*(.+)$")
    if not m:
        return None, adopt, disq
    if re.match(r"\s*none\b", m.group(1), re.I):
        return "NONE", [], disq
    out = []
    for x in re.findall(r"\d+", m.group(1)):
        k = int(x)
        if k in valid and k not in out:
            out.append(k)
    return (out or None), adopt, disq

def _copy_small_tree(src_dir, dst_dir):
    """Copy a scout directory into the unit (files up to SCOUT_COPY_MAX_B each; caches and vendored trees skipped) -> [relative paths]."""
    got = []
    for root, dirs, files in os.walk(src_dir):
        dirs[:] = [d for d in dirs if d not in REUSE_SKIP_DIRS and not any(x.endswith((".dist-info", ".egg-info")) for x in dirs)]
        for f in files:
            p = os.path.join(root, f)
            try:
                if os.path.getsize(p) > SCOUT_COPY_MAX_B:
                    continue
                rel = os.path.relpath(p, src_dir)
                os.makedirs(os.path.dirname(os.path.join(dst_dir, rel)), exist_ok=True)
                shutil.copy2(p, os.path.join(dst_dir, rel))
                got.append(rel)
            except OSError:
                pass
    return got


def _cand_line(k, c):
    return "scout %d (%s): %s | PoC: %s | supports=%s" % (k, str(c.get("angle") or SCOUT_ANGLES[(k - 1) % len(SCOUT_ANGLES)])[:60],
        str(c.get("hypothesis"))[:240], str((c.get("poc") or {}).get("finding") or "-")[:200], c.get("supports"))

def scout_round(u, grant, job=None):
    """After a C, BEFORE any archive: SCOUT_K scouts on SCOUT_K angles read the unit's directory (read-only), propose root causes and test them with
    a PoC in parallel on the unit's grant; a panel of SCOUT_PANEL critics ranks them (Borda) and may adopt compatible others. A running job (a
    checkpoint C) keeps running. Returns {"winner": k|None, "adopt": [k], "res": {k: dir info}, "note": text} - the caller archives and restarts
    on a winner, and fixes in place when there is none."""
    uid = u["id"]
    u["scouted"] = int(u.get("scouted") or 0) + 1
    with STATE_LOCK:
        RUN["scouts"] = RUN.get("scouts", 0) + 1
    n = u["scouted"]
    base = os.path.join(PD, "scouts", "%s.s%d" % (uid, n))
    os.makedirs(base, exist_ok=True)
    arch = "/workspace/%s" % uid
    cores = max(1, int((grant or {}).get("cores") or 1) // SCOUT_K)
    mem = max(2, int((grant or {}).get("mem_gb") or 6) // SCOUT_K)
    spec = "/workspace/%s/spec.md" % uid
    hist = u.get("scout_hist") or []
    tried = ("\nALREADY TESTED in earlier scout rounds of this unit (build on them; do not repeat a refuted hypothesis): " + " || ".join(hist[-6:])) if hist else ""
    bank = bank_scout_block(uid, arch)
    running = ("; its registered job pid %s is STILL RUNNING - its files may grow, never stop it" % job.get("pid")) if job else ""
    ledger({"kind": "scout_start", "unit": uid, "k": SCOUT_K, "cores_each": cores, "mem_each": mem, "n_episode": RUN["scouts"], "n_unit": n, "job_running": bool(job)})
    log("%s: SCOUTING after grade C - %d scouts (%d core(s), %d GB each, %d min), then a panel of %d critics" % (uid, SCOUT_K, cores, mem, SCOUT_T // 60, SCOUT_PANEL))
    res = {}
    def one(k):
        sdir = os.path.join(base, "s%d" % k)
        os.makedirs(sdir, exist_ok=True)
        wsd = _ws_name(sdir)
        try:
            r = run_call(SCOUT_PROMPT.format(k=k, K=SCOUT_K, uid=uid, archive=arch, running=running, sdir=wsd, spec=spec,
                                             angle=SCOUT_ANGLES[(k - 1) % len(SCOUT_ANGLES)], tried=tried, poc_min=SCOUT_POC_MIN, cores=cores,
                                             mins=SCOUT_T // 60, bank=bank),
                         slot(SCOUT_T), "scout%d_%s" % (k, uid), wrapup=SCOUT_WRAP.format(sdir=wsd), grant={"cores": cores, "mem_gb": mem}, cwd=sdir,
                         wrap_t=SCOUT_WRAP_T)
        except Exception as e:
            log("%s: scout %d failed: %s" % (uid, k, e))
            r = {"rc": -2, "tokens": 0}
        c = _read_candidate(sdir)
        res[k] = {"dir": wsd, "real": sdir, "cand": c}
        ledger({"kind": "scout_done", "unit": uid, "k": k, "valid": bool(c), "supports": (c or {}).get("supports"), "tokens": r.get("tokens"), "rc": r.get("rc")})
    ths = [threading.Thread(target=one, args=(k,), name="scout%d_%s" % (k, uid), daemon=True) for k in range(1, SCOUT_K + 1)]
    for t in ths:
        t.start()
    for t in ths:
        t.join()
    for k in range(1, SCOUT_K + 1):   # no scout computation outlives the scouting (the unit's own job, if any, is not touched)
        try:
            _kill_marked("scout%d_%s" % (k, uid), 9)
        except Exception:
            pass
    valid = dict((k, v) for k, v in res.items() if v["cand"])
    u["scout_hist"] = hist + ["%s (supports=%s: %s)" % (str(v["cand"].get("hypothesis"))[:160], v["cand"].get("supports"),
                                                         str((v["cand"].get("poc") or {}).get("finding") or "-")[:120]) for k, v in sorted(valid.items())]
    out = {"winner": None, "adopt": [], "disq": [], "res": res, "note": ""}
    def fallback(why, disq=()):
        out["disq"] = sorted(disq)
        ledger({"kind": "scout_fallback", "unit": uid, "why": why, "valid": sorted(valid), "disqualified": sorted(disq)})
        log("%s: scouting gave no winner (%s) -> the unit is fixed in place" % (uid, why))
        if valid:
            out["note"] = ("SCOUTING found no admissible route - the candidates checked (an unsupported hypothesis stays refuted unless you find new "
                           "evidence): " + " || ".join(_cand_line(k, v["cand"]) + (DISQ_MARK if k in disq else "") for k, v in sorted(valid.items())))
        return out
    if not valid:
        return fallback("no valid candidate")
    if OVERRIDE.is_set():
        return fallback("override")
    sel = scout_select(uid, base, valid, arch, spec)
    if sel.get("fallback"):
        return fallback(sel["fallback"], sel.get("disq") or ())
    out.update(winner=sel["winner"], adopt=sel["adopt"], disq=sel.get("disq") or [])
    return out

def scout_select(uid, base, valid, arch, spec):
    """The selection panel: SCOUT_PANEL critics rank the valid candidates side by side (Borda); the winner is the best-ranked SUPPORTED one,
    adopted = the other supported candidates a majority names. -> {"winner", "adopt"} or {"fallback": why}."""
    spare_min = max(0, int(usable_left() / 60))
    dirs = ", ".join("scout %d: %s/" % (k, v["dir"]) for k, v in sorted(valid.items()))
    sel = {}
    def judge(j):
        outf = os.path.join(base, "select%d.md" % j)
        try:
            run_call(SELECT_PROMPT.format(uid=uid, n=len(valid), dirs=dirs, archive=arch, spec=spec, spare_min=spare_min, out=_ws_name(outf)),
                     slot(SCOUT_SELECT_T), "criticsel%d_%s" % (j, uid), wrapup=SELECT_WRAP.format(out=_ws_name(outf)), cwd=base, wrap_t=SCOUT_WRAP_T)
        except Exception as e:
            log("%s: selection critic %d failed: %s" % (uid, j, e))
        sel[j] = _parse_rank(read(outf), set(valid))
    ths = [threading.Thread(target=judge, args=(j,), name="criticsel%d_%s" % (j, uid), daemon=True) for j in range(1, SCOUT_PANEL + 1)]
    for t in ths:
        t.start()
    for t in ths:
        t.join()
    ranks = [v[0] for v in sel.values() if isinstance(v[0], list)]
    nones = sum(1 for v in sel.values() if v[0] == "NONE")
    pts = dict((k, 0) for k in valid)
    for rk in ranks:
        for i, k in enumerate(rk):
            pts[k] += len(valid) - 1 - i
    if nones * 2 > SCOUT_PANEL or not ranks:
        ledger({"kind": "scout_select", "unit": uid, "ranks": dict((str(j), v[0]) for j, v in sel.items()), "nones": nones})
        return {"fallback": "the panel found no supported candidate" if ranks or nones else "no ranking", "disq": []}
    dq_votes = {}
    for v in sel.values():
        for k in (v[2] or []):
            dq_votes[k] = dq_votes.get(k, 0) + 1
    disq = sorted(k for k, n_ in dq_votes.items() if n_ * 2 > SCOUT_PANEL)   # a majority's disqualification (criterion 2) is binding
    ranked = [k for k in sorted(pts, key=lambda k: (-pts[k], k)) if valid[k]["cand"].get("supports") and k not in disq]
    if not ranked:   # the winner, like every adopted candidate, is supported by its PoC and not disqualified
        ledger({"kind": "scout_select", "unit": uid, "ranks": dict((str(j), v[0]) for j, v in sel.items()), "points": dict((str(k), p) for k, p in pts.items()),
                "nones": nones, "disq_votes": dict((str(k), n_) for k, n_ in dq_votes.items()), "disqualified": disq})
        sup = [k for k in pts if valid[k]["cand"].get("supports")]
        return {"fallback": "the panel disqualified every supported candidate" if sup else "no ranked candidate is supported by its PoC", "disq": disq}
    win = ranked[0]
    votes = {}
    for v in sel.values():
        for k in (v[1] or []):
            if k != win:
                votes[k] = votes.get(k, 0) + 1
    adopt = sorted(k for k, nv in votes.items() if nv * 2 > SCOUT_PANEL and valid[k]["cand"].get("supports") and k not in disq)
    ledger({"kind": "scout_select", "unit": uid, "ranks": dict((str(j), v[0]) for j, v in sel.items()), "adopt_votes": dict((str(k), n_) for k, n_ in votes.items()),
            "points": dict((str(k), p) for k, p in pts.items()), "nones": nones, "disq_votes": dict((str(k), n_) for k, n_ in dq_votes.items()),
            "disqualified": disq, "winner": win, "adopt": adopt})
    return {"winner": win, "adopt": adopt, "disq": disq}

def scout_note(uid, sc):
    """The restart preamble's account of the selected route (the winner's files are in /workspace/<uid>/from_scout/, adopted ones beside)."""
    valid = dict((k, v) for k, v in sc["res"].items() if v["cand"])
    win, c = sc["winner"], valid[sc["winner"]]["cand"]
    ad = " ".join("ALSO ADOPTED (apply this change as well; its files are in /workspace/%s/from_scout_%d/): %s Its PoC: %s. Its plan: %s."
                  % (uid, k, str(valid[k]["cand"].get("hypothesis"))[:300], str((valid[k]["cand"].get("poc") or {}).get("finding") or "-")[:200],
                     json.dumps(valid[k]["cand"].get("plan"), ensure_ascii=False)[:400]) for k in sc["adopt"])
    others = [_cand_line(k, v["cand"]) + (DISQ_MARK if k in (sc.get("disq") or ()) else "") for k, v in sorted(valid.items()) if k != win and k not in sc["adopt"]]
    return ("SCOUTING: after the failed round %d scouts each tested a root-cause hypothesis with a small proof-of-concept; a panel of %d critics picked "
            "scout %d. Its hypothesis: %s Its evidence: %s Its PoC: %s (command: %s). Its plan: %s. Its code and PoC outputs are in /workspace/%s/from_scout/ - "
            "re-run its PoC once, then carry the plan to full scale (the executor rules still apply). %s The other candidates, your alternatives if "
            "this route fails: %s"
            % (len(valid), SCOUT_PANEL, win, str(c.get("hypothesis"))[:400], str(c.get("evidence") or "-")[:300],
               str((c.get("poc") or {}).get("finding") or "-")[:300], str((c.get("poc") or {}).get("command") or "-")[:160],
               json.dumps(c.get("plan"), ensure_ascii=False)[:700], uid, ad, " || ".join(others) or "(none)"))

def scout_seed(uid, sc):
    """Copy the winner's (and every adopted candidate's) files into the unit directory (the fresh one after an archive)."""
    valid = dict((k, v) for k, v in sc["res"].items() if v["cand"])
    got = _copy_small_tree(valid[sc["winner"]]["real"], os.path.join(unit_dir(uid), "from_scout"))
    for k in sc["adopt"]:
        _copy_small_tree(valid[k]["real"], os.path.join(unit_dir(uid), "from_scout_%d" % k))
    ledger({"kind": "scout_winner", "unit": uid, "winner": sc["winner"], "adopt": sc["adopt"], "files": len(got)})
    log("%s: scout %d wins%s - its files copied to /workspace/%s/from_scout/" % (uid, sc["winner"], (", adopted %s" % sc["adopt"]) if sc["adopt"] else "", uid))

def scout_readings(uid, sc):
    """The winner's and the adopted candidates' reading changes, checked against their evidence files as the scouting left them (before any
    archive moves the unit's files) and propagated."""
    if not sc.get("winner"):
        return
    valid = dict((k, v) for k, v in sc["res"].items() if v["cand"])
    for k in [sc["winner"]] + list(sc["adopt"]):
        rc = valid[k]["cand"].get("reading_change")
        if rc and not _evidence_exists(uid, str(rc.get("evidence") or ""), base=valid[k]["real"]):   # the same rule as a critic's change
            ledger({"kind": "reading_change_rejected", "unit": uid, "id": rc.get("id"), "why": "no evidence file", "evidence": str(rc.get("evidence") or "")[:200],
                    "source": "scout %d" % k})
        elif rc:
            apply_reading_change(str(rc["id"]).strip(), str(rc["reading"])[:600], str(rc.get("evidence") or "")[:300], uid, "scout")

# ---------------------------------------------------------------- propagation: ONE rule - an input a unit consumed changed (upstream files, READINGS.md)
def apply_reading_change(kid, reading, evidence, by_uid, source):
    """A reading changes (a critic's FIX_PLAN reading_change with its evidence file, or an adopted scout candidate): READINGS.md gets the new version;
    every unit that consumed READINGS.md then sees the change through the input rule. A flip back to an earlier reading needs new evidence."""
    kid = str(kid).strip().upper()
    norm = lambda x: re.sub(r"\W+", " ", str(x or "")).strip().lower()
    with STATE_LOCK:
        rd = RUN.setdefault("readings", [])
        ent = next((x for x in rd if str(x.get("id")).upper() == kid), None)
        if ent is not None and norm(ent.get("reading")) == norm(reading):
            return False
        if ent is not None and ent.get("history"):   # one change per reading per episode: later conflicting evidence is a note for the report
            RUN.setdefault("reading_conflicts", []).append({"id": kid, "reading": reading[:300], "evidence": evidence[:200], "by": by_uid})
            ledger({"kind": "reading_change_rejected", "unit": by_uid, "id": kid, "why": "already changed once this episode", "evidence": evidence[:200]})
            return False
        if ent is None:
            ent = {"id": kid, "F": "-", "reading": reading, "version": 0}
            rd.append(ent)
        ent.setdefault("history", []).append({"version": int(ent.get("version") or 1), "reading": ent.get("reading"), "evidence": evidence})
        old = ent.get("reading")
        ent["version"] = int(ent.get("version") or 1) + 1
        ent["reading"] = reading
        ent["changed"] = "%s (was: %s; evidence: %s; by %s, %s)" % (reading, str(old)[:200], evidence or "-", by_uid, source)
        SCHED_CV.notify_all()
    write_readings(RUN["readings"])
    try:
        _atomic_json_dump(RUN["readings"], os.path.join(PD, "readings.json"))
    except Exception:
        pass
    ledger({"kind": "reading_change", "id": kid, "version": ent["version"], "reading": reading[:300], "evidence": (evidence or "")[:200], "by": by_uid, "source": source})
    log("READING CHANGE %s -> v%d by %s (%s): %s" % (kid, ent["version"], by_uid, source, reading[:160]))
    propagate_inputs(exclude=by_uid)
    return True

def _quick_sig(rp):
    """(size, mtime) of a file / (count, total size, newest mtime) of a directory (bounded) / None when absent."""
    try:
        if os.path.isdir(rp):
            n = tot = newest = 0
            for root, dirs, files in os.walk(rp):
                dirs[:] = [d for d in dirs if d not in REUSE_SKIP_DIRS]
                for fn in files:
                    try:
                        st = os.stat(os.path.join(root, fn))
                    except OSError:
                        continue
                    n += 1; tot += st.st_size; newest = max(newest, int(st.st_mtime))
                    if n > 5000:
                        return [n, tot, newest]
            return [n, tot, newest]
        st = os.stat(rp)
        return [st.st_size, int(st.st_mtime)]
    except OSError:
        return None

def _file_hash(p, chunk=1 << 20):
    h = hashlib.sha1()
    try:
        sz = os.path.getsize(p)
        with open(p, "rb") as f:
            h.update(f.read(chunk))
            if sz > 2 * chunk:
                f.seek(-chunk, 2)
                h.update(f.read(chunk))
        h.update(str(sz).encode())
    except OSError:
        return None
    return h.hexdigest()

def _content_sig(rp):
    """Content signature (heads and tails of the files, sizes, names) - a rewrite with identical content is no change."""
    if os.path.isdir(rp):
        h, n = hashlib.sha1(), 0
        for root, dirs, files in os.walk(rp):
            dirs[:] = sorted(d for d in dirs if d not in REUSE_SKIP_DIRS)
            for fn in sorted(files):
                n += 1
                if n > 2000:
                    break
                fp = os.path.join(root, fn)
                h.update(os.path.relpath(fp, rp).encode("utf-8", "surrogateescape"))   # any file name
                h.update(str(_file_hash(fp, 65536)).encode())
        return h.hexdigest()
    return _file_hash(rp) if os.path.exists(rp) else None

def record_inputs(u):
    """The unit's consumed inputs, fingerprinted: its needs files, its upstreams' declared deliverables, and READINGS.md (+ the reading versions)."""
    fp = {}
    paths = []
    for d in (u.get("depends_on") or []):
        du_ = unit_by_id(d) or {}
        paths += need_paths((u.get("needs") or {}).get(d), d) + [x for x in (du_.get("deliverables") or []) if isinstance(x, str)]
    if u.get("type") == "produce":
        paths.append("/workspace/READINGS.md")
    for p in paths[:40]:
        if any(ch in p for ch in "*?[{<") or p in fp:
            continue
        rp = _ws_path(p)
        q = _quick_sig(rp)
        if q is not None:
            fp[p] = {"q": q, "h": _content_sig(rp)}
    u["inputs"] = fp
    u["readings_v"] = dict((str(x.get("id")), int(x.get("version") or 1)) for x in (RUN.get("readings") or []))

def upstream_changes(u):
    """Inputs this unit consumed whose CONTENT changed since they were recorded -> [path] (a rewrite with the same content is no change)."""
    out = []
    for p, sig in list((u.get("inputs") or {}).items()):
        rp = _ws_path(p)
        q = _quick_sig(rp)
        if q == sig.get("q"):
            continue
        if q is None:
            out.append(p + " (gone)")
            continue
        h = _content_sig(rp)
        if h == sig.get("h"):
            sig["q"] = q
            continue
        out.append(p)
    return out

def change_notice(u):
    """The facts of input changes the unit has not been audited against yet (orchestrator truth), for its prompts and audits."""
    ch = upstream_changes(u)
    if not ch:
        return ""
    L = ["INPUT CHANGED since this unit consumed it (orchestrator facts): %s - check whether this unit used the old content and what must be recomputed."
         % ", ".join(ch[:12])]
    if "/workspace/READINGS.md" in ch:
        seen = u.get("readings_v") or {}
        for x in (RUN.get("readings") or []):
            if int(x.get("version") or 1) > int(seen.get(str(x.get("id")), 1)):
                L.append("READINGS CHANGED: %s v%d: %s" % (x.get("id"), int(x.get("version") or 1), str(x.get("changed") or x.get("reading"))[:400]))
    return "\n".join(L)

def propagate_inputs(exclude=None):
    """Every DONE produce unit whose consumed inputs changed is flagged for a reopen (a delta audit of the change); running units see the change in
    their next prompt and audit (change_notice)."""
    with STATE_LOCK:
        cands = [v for v in RUN["plan"] if isinstance(v, dict) and v.get("type") == "produce" and v.get("status") == "done"
                 and v.get("id") != exclude and not v.get("reopen")]
    found = [(v, change_notice(v)) for v in cands]   # content hashing outside the lock (the time trigger never waits on it)
    with STATE_LOCK:
        for v, n in found:
            if n and v.get("status") == "done" and not v.get("reopen"):
                v["reopen"] = {"why": n, "t": time.time()}
                ledger({"kind": "input_changed", "unit": v["id"], "notice": n[:400]})
        SCHED_CV.notify_all()

# ---------------------------------------------------------------- the resource pool: one admission rule; the GPU is a token
def _units_rss_gb():
    """Measured resident memory (GB) of every process of THIS episode's units (PECE_UNIT marker) - what the running units really use."""
    needle, tot = ("PECE_UNIT=%s:" % RUN_ID).encode(), 0
    for pid in os.listdir("/proc"):
        if not pid.isdigit():
            continue
        try:
            with open("/proc/%s/environ" % pid, "rb") as f:
                if needle not in f.read():
                    continue
            with open("/proc/%s/status" % pid) as f:
                for line in f:
                    if line.startswith("VmRSS:"):
                        tot += int(line.split()[1])
                        break
        except Exception:
            pass
    return tot / (1024.0 * 1024.0)

RSS_CACHE = {"gb": 0.0, "t": 0.0, "live": False}

def rss_sampler():
    """Daemon: the units' measured memory every 30 s, outside every lock (a /proc read can block on a stuck process)."""
    RSS_CACHE["live"] = True
    while not STOP.is_set():
        try:
            RSS_CACHE["gb"], RSS_CACHE["t"] = _units_rss_gb(), time.time()
        except Exception:
            pass
        STOP.wait(30)

def _rss_now():
    """The sampler's figure; an inline scan only where no sampler runs (the offline tests)."""
    return RSS_CACHE["gb"] if RSS_CACHE["live"] else _units_rss_gb()

class ResourcePool:
    """Cores + memory of the node's allocation across the running units (no CPU pinning). A request gets its declaration when the declarations
    fit. Otherwise - a repair round at once, a first launch after POOL_WAIT_S of readiness - it gets min(declared, max(2, free)) cores (cores may
    be oversubscribed) and its declared memory when the node's MEASURED use leaves room for it; a first launch waits for real memory, a repair
    round takes what is really free (at least 4 GB). A ready unit never starves behind inflated declarations."""
    def __init__(self, ncpus, mem_gb):
        self.lock = threading.RLock()
        self.ncpus = max(1, int(ncpus))
        self.mem_gb = int(mem_gb) if (mem_gb and mem_gb > 0) else 0
        self.grants = {}

    def clamp(self, unit):
        try:
            cores = int(unit.get("cores") or self.ncpus)
        except Exception:
            cores = self.ncpus
        cores = min(max(1, cores), self.ncpus)
        try:
            mem = float(unit.get("mem_gb") or (self.mem_gb or 1))
        except Exception:
            mem = float(self.mem_gb or 1)
        mem = max(1, int(round(mem)))
        if self.mem_gb > 0:
            mem = min(mem, self.mem_gb)
        return cores, mem

    def used(self):
        with self.lock:
            return (sum(g["cores"] for g in self.grants.values()), sum(g["mem_gb"] for g in self.grants.values()))

    def acquire(self, uid, unit, waited_s=0.0, first=True):
        """Non-blocking; the grant dict, or None (a first launch that does not fit and either waited less than POOL_WAIT_S or finds no real memory)."""
        cores, mem = self.clamp(unit)
        with self.lock:
            if uid in self.grants:
                return self.grants[uid]
            uc, um = self.used()
            fc, fm = self.ncpus - uc, ((self.mem_gb - um) if self.mem_gb > 0 else mem)
            if cores <= fc and mem <= fm:
                g = {"uid": uid, "cores": cores, "mem_gb": mem, "t": time.time()}
            elif (not first) or waited_s >= POOL_WAIT_S:
                c = max(1, min(cores, max(2, fc)))
                if self.mem_gb <= 0 or mem <= fm:
                    m, real = mem, None
                else:
                    real = self.mem_gb * 0.9 - _rss_now()
                    if real >= mem:
                        m = mem
                    elif not first:
                        m = max(4, min(mem, int(real)))
                    else:
                        return None
                g = {"uid": uid, "cores": c, "mem_gb": m, "t": time.time(), "shared": True, "reduced": bool(c < cores or m < mem),
                     "measured_free_gb": (round(real, 1) if real is not None else None)}
            else:
                return None
            self.grants[uid] = g
        if g.get("shared"):
            ledger({"kind": "pool_shared", "unit": uid, "declared": [cores, mem], "cores": g["cores"], "mem_gb": g["mem_gb"], "first": first,
                    "waited_s": int(waited_s), "pool_used": list(self.used()), "measured_free_gb": g.get("measured_free_gb")})
        return g

    def acquire_free(self, uid, want=2):
        """Up to `want` free cores now (at least 1) - the report agent starts even while flushing units hold grants."""
        with self.lock:
            if uid in self.grants:
                return self.grants[uid]
            uc, um = self.used()
            n = max(1, min(want, self.ncpus - uc))
            g = {"uid": uid, "cores": n, "mem_gb": max(1, (self.mem_gb - um) if self.mem_gb > 0 else 1), "t": time.time(), "shared": self.ncpus - uc < 1}
            self.grants[uid] = g
            return g

    def release(self, uid):
        with self.lock:
            g = self.grants.pop(uid, None)
        if g:
            with SCHED_CV:
                SCHED_CV.notify_all()
        return g

POOL = None
SCHED_CV = threading.Condition(STATE_LOCK)
THREADS = {}
TERMINAL = ("done", "failed", "blocked", "flushed")

# ---------------------------------------------------------------- scheduling helpers

def unit_by_id(uid, plan=None):
    for u in (plan if plan is not None else RUN["plan"]):
        if isinstance(u, dict) and u.get("id") == uid:
            return u
    return None


def deps_done(u):
    """Readiness: every dependency is done (the critic has spoken) or passes the FILE GATE (a running unit whose valid handoff names the files this
    unit needs, unchanged for FILE_GATE_S). The dependent then starts PROVISIONALLY (its prompt says so) instead of idling through the upstream's
    fix rounds. Nothing else counts."""
    for d in (u.get("depends_on") or []):
        du = unit_by_id(d)
        if du is None:
            return False
        if du.get("status") == "done" or (du.get("status") == "running" and _file_gate_ok(u, d, du)):
            continue
        return False
    return True

def _file_gate_ok(u, d, du):
    """FILE GATE: the upstream d has a valid handoff and every file u needs from it exists (a pattern: at least one match) and has been unchanged
    for FILE_GATE_S -> the dependent may start on it PROVISIONALLY (its audit follows; its inputs are fingerprinted)."""
    if not du.get("handoff_valid_at"):
        return False
    paths = need_paths((u.get("needs") or {}).get(d), d)
    if not paths:
        return False
    now_ = time.time()
    for p in paths:
        pat = re.sub(r"<[^<>/]*>", "*", p)
        hits = []
        for alt in _brace_expand(_ws_path(pat)):
            hits += glob.glob(alt) if _has_glob(alt) else ([alt] if os.path.exists(alt) else [])
        if not hits:
            return False
        for h in hits[:200]:
            try:
                if now_ - os.stat(h).st_mtime < FILE_GATE_S:
                    return False
            except OSError:
                return False
    return True

def provisional_deps(u):
    """{dep id: "file"} for the dependencies of u that run without a final verdict (they passed the file gate)."""
    out = {}
    for d in (u.get("depends_on") or []):
        du = unit_by_id(d) or {}
        if du.get("status") == "running" and _file_gate_ok(u, d, du):
            out[d] = "file"
    return out


def _g13_pass(gates):
    """G1 and G3 pass (a B for a located G2 code error qualifies for the incremental re-audit; dependents still need _g123_pass)."""
    return bool(gates) and all(str((gates or {}).get(k, "")).lower() == "pass" for k in ("G1", "G3"))


def _g123_pass(gates):
    """G1, G2 and G3 all pass in the critic's GATES line (a grade B whose fix list is the only open item)."""
    return bool(gates) and all(str((gates or {}).get(k, "")).lower() == "pass" for k in ("G1", "G2", "G3"))


def downstream_ids(uid, plan):
    """Transitive dependents of uid in plan order."""
    out, changed = [], True
    while changed:
        changed = False
        for u in plan:
            if isinstance(u, dict) and u.get("id") not in out and u.get("id") != uid and any(d == uid or d in out for d in (u.get("depends_on") or [])):
                out.append(u["id"])
                changed = True
    return out


def _prev_verdict_note(u):
    """The newest archived round's critic verdict (grade + first defect lines) for a unit flushed before its redo was audited."""
    for a in reversed(u.get("archives") or []):
        txt = read(os.path.join(_ws_path(a), "critic_report.md"))
        if not txt:
            continue
        g = re.match(r"\s*GRADE:\s*([ABCDW])", txt)
        m = re.search(r"(?:FIX LIST|WHAT IS WRONG|RESIDUAL)(.*?)(?:\n[A-Z][A-Z /]{3,}\n|\nFIX_PLAN:|\Z)", txt, re.S)
        body = " ".join(l.strip() for l in (m.group(1) if m else txt[:600]).strip().splitlines() if l.strip())[:400]
        return "redo flushed before its audit; the previous round (%s) was graded %s - its defects: %s" % (a, g.group(1) if g else "?", body or "(see its critic_report.md)")
    return ""

def _gap_note(uid):
    """The unmet rows of a unit settled DONE WITH GAP (its critic's G3 line / missed ANCHORS rows), for dependents and the report."""
    txt = read(os.path.join(unit_dir(uid), "critic_report.md"))
    rows = _anchor_missed(txt)
    if not rows:
        mm = re.search(r"G3=hit[^\n]*", txt)
        rows = [mm.group(0)] if mm else ["(see its critic_report.md)"]
    return " ; ".join(r[:200] for r in rows[:6])

def settle(u, status, reason, grade, rounds):
    """The terminal transition of a unit: status + grade + ledger, and EVERY settle stops the unit's processes (a job left running could rewrite files
    its dependents have started to read). failed: its produce dependents are blocked and one branch replan is requested. done: done
    dependents whose inputs changed are reopened. gap = done with its unmet rows stated (the data flow on)."""
    uid = u["id"]
    gap = status == "gap"
    status = "done" if gap else status
    try:   # stop the unit's processes BEFORE the status flips (no dependent can launch on files a leftover still writes)
        killed = reap_leftovers(uid)
        if killed:
            ledger({"kind": "settle_reaped", "unit": uid, "status": status, "n": len(killed)})
    except Exception as e:
        log("%s: reap at settle failed: %s" % (uid, e))
    with SCHED_CV:
        u["status"], u["t_settle"], u["settle_reason"] = status, time.time(), reason
        u.pop("waiting", None)
        u.pop("reopen", None)
        try:
            if status == "flushed":
                note = u.pop("override_note", None) or _prev_verdict_note(u)
                if note:
                    u["flush_note"] = note
                    ledger({"kind": "flush_unaudited", "unit": uid, "note": note[:400]})
            if status in ("done", "failed"):
                RUN["grades"][uid] = ("A" if (status == "done" and not gap and reason in ("A", "reaudit_A")) else (grade or ("B" if status == "done" else "U")))
            if gap:
                u["gap"] = True
                u["gap_unaudited"] = str(reason).startswith("gap_unaudited")
                u["gap_note"] = _gap_note(uid)
                ledger({"kind": "unit_gap", "unit": uid, "grade": grade, "rounds": rounds, "reason": reason, "note": u["gap_note"][:600]})
                log("%s: DONE WITH GAP (grade %s, %s): the data flow on; unmet: %s" % (uid, grade, reason, u["gap_note"][:300]))
            elif status == "done" and not str(reason).startswith("reopen"):
                u.pop("gap", None)
            if status == "failed" and uid not in RUN["failed"]:
                RUN["failed"].append(uid)
        except Exception as e:
            log("%s: settle bookkeeping failed: %s" % (uid, e))
        ledger({"kind": "settle", "unit": uid, "status": status, "reason": reason, "grade": RUN["grades"].get(uid), "rounds": rounds, "gap": gap})
        log("%s -> %s (%s; grade %s, %d repair round(s))" % (uid, ("DONE WITH GAP" if gap else status.upper()), reason, RUN["grades"].get(uid), rounds))
        SCHED_CV.notify_all()
    if POOL:
        POOL.release(uid)
    if status == "failed":
        try:
            if os.path.isdir(unit_dir(uid)):
                ensure_residual(uid, "retired: %s" % reason)
        except Exception as e:
            log("%s: residual at retirement failed: %s" % (uid, e))
        with SCHED_CV:
            RUN["retired"].append(uid)
            blocked = []
            for y in downstream_ids(uid, RUN["plan"]):
                yu = unit_by_id(y)
                if yu is None or yu.get("type") == "render" or yu.get("status") in ("running",) + TERMINAL:
                    continue
                yu["status"], yu["blocked_by"] = "blocked", uid
                blocked.append(y)
                ledger({"kind": "settle", "unit": y, "status": "blocked", "reason": "upstream %s retired" % uid, "upstream": uid})
            if RUN["replans"] < 1 and not OVERRIDE.is_set() and usable_left() >= MIN_ATTEMPT_S and blocked:
                RUN["replans"] += 1
                RUN["replan_req"] = {"uid": uid, "reason": reason, "blocked": blocked}
                ledger({"kind": "replan_trigger", "unit": uid, "reason": reason, "blocked": blocked, "replan": RUN["replans"]})
            elif blocked:
                ledger({"kind": "replan_cap", "unit": uid, "reason": reason, "blocked": blocked, "why": "override" if OVERRIDE.is_set() else "no_time_or_cap"})
            SCHED_CV.notify_all()
    if status == "done" and u.get("type") == "produce":
        try:
            propagate_inputs(exclude=uid)
        except Exception as e:
            log("%s: propagation failed: %s" % (uid, e))
    checkpoint()

def override_hold(u, g, action, why):
    """After the override a verdict never restarts, archives, retires or re-opens a unit - anything but a settled done becomes a note."""
    if not OVERRIDE.is_set() or action in ("done", "gap"):
        return False
    u["override_note"] = "the audit at the override graded %s (%s) - not acted on; the unit's files stay as they were" % (g, why)
    ledger({"kind": "override_verdict_held", "unit": u.get("id"), "grade": g, "action": action, "reason": why})
    return True

# ---------------------------------------------------------------- the executor's prompts
def exec_prompt(u, restart=None):
    """EXEC prompt (budget at launch = the usable wall) + the upstream units; restart = the record of the archived round (preamble + ONE ruling
    block: the scout plan when scouting ran, else the previous critic's REDUCIBLE ruling and the budget note)."""
    uid = u["id"]
    budget = max(0.0, usable_left())
    deps = [d for d in (u.get("depends_on") or []) if unit_by_id(d) is not None]
    up = ""
    if deps:
        prov = provisional_deps(u)
        up = (" UPSTREAM UNITS you depend on (%s): %s - read each /workspace/<id>/handoff.json FIRST, then open the files it lists; the files are the "
              "truth, the prose is a claim." % ("all final" if not prov else "%s not final" % ", ".join(prov),
                 "; ".join("%s -> /workspace/%s/%s" % (d, d, PROVISIONAL_FILE_TAG if d in prov else "") for d in deps)))
    body = EXEC_PROMPT.format(uid=uid, upstream=up, budget_s=int(budget), budget_h=budget / 3600.0,
                              knobs=json.dumps(u.get("scale_knobs") or [], ensure_ascii=False)[:400]) + _exec_notes(u) + bank_start_block(u, restart)
    if restart:
        cp_, cd_ = restart.get("copied") or [], restart.get("code") or []
        note = restart.get("note") or ""
        body = RESTART_PREAMBLE.format(uid=uid, grade=restart.get("grade"), archive=restart["archive"], round=restart.get("round"),
                                       code=((" and the previous round's CODE files (%d copied back as your starting point - fix or redesign exactly the parts "
                                              "residual.md faults and keep the rest; when the scouting note or residual.md says the route itself is wrong, that "
                                              "code is reference only)" % len(cd_)) if cd_ else " only (an otherwise empty directory)"),
                                       copied=(" (%d file(s): %s)" % (len(cp_), ", ".join(cp_[:12]) + (" ..." if len(cp_) > 12 else ""))) if cp_ else " (none were listed)",
                                       note=(" " + note) if note else "") + body
    return body

def _exec_notes(u):
    """Change notices for the executor: readings changed and upstream files changed since the unit launched (orchestrator facts)."""
    n = change_notice(u)
    return ("\n\nCHANGE NOTICE (orchestrator facts - act on them in this session):\n" + n) if n else ""

def _handoff_sig(uid):
    p = os.path.join(unit_dir(uid), "handoff.json")
    try:
        with open(p, "rb") as f:
            return hashlib.sha1(f.read()).hexdigest()
    except OSError:
        return None

def call_outcome(uid, r, sig_before):
    """HANDOFF (a normal turn end with a handoff.json written in the call, or a cut call whose new handoff registers a live job) | HANDOFF_BAD
    (written in the call, unparseable) | CUT (a time limit, a stream cut, a crash - even after writing a handoff) | CUT_NOHAND (the turn ended
    without writing handoff.json) | INFRA | INTERRUPTED. A CUT is continued, never audited (an mtime rule alone would audit
    half-finished sessions that rewrote the handoff mid-way)."""
    if r.get("interrupted") or OVERRIDE.is_set():
        return "INTERRUPTED"
    if r.get("infra"):
        return "INFRA"
    sig = _handoff_sig(uid)
    if sig is not None and sig != sig_before:
        try:
            h = json.load(open(os.path.join(unit_dir(uid), "handoff.json")))
        except Exception:
            return "HANDOFF_BAD"
        if r.get("rc") == 0:
            return "HANDOFF"
        wt = waiting_spec(h)[0] if isinstance(h, dict) else None
        if wt and _pid_alive_unit(wt["pid"], uid):
            return "HANDOFF"
        return "CUT"
    if r.get("rc") == 0 and sig is not None:   # a normal turn end that confirms a handoff written in this round (after the unit's last look)
        try:
            if os.stat(os.path.join(unit_dir(uid), "handoff.json")).st_mtime >= LAST_LOOK.get(uid, T0):
                h = json.load(open(os.path.join(unit_dir(uid), "handoff.json")))
                wt = waiting_spec(h)[0] if isinstance(h, dict) else None
                if not (wt and _stale_wait(uid, wt)):   # a registration already served is the previous narrative, not a handoff
                    return "HANDOFF"
        except Exception:
            pass
    return "CUT_NOHAND" if r.get("rc") == 0 else "CUT"

def _cut_why(kind, r):
    if kind == "CUT_NOHAND":
        return ("your previous session ended its turn but /workspace/{uid}/handoff.json was not (re)written - if the work is complete, rewrite "
                "handoff.json now (that ends your turn); otherwise finish it first.")
    if r.get("rc") == -1:
        return "your previous session reached its time limit while you were still working."
    return "your previous session ended abnormally (exit %s) - check what it left." % r.get("rc")

def _fix_carry(S):
    """A fix round's instructions, carried into every continuation of that round (they stay in force until the next verdict)."""
    return ("\n\nTHE FIX ROUND'S INSTRUCTIONS (still in force - finish them):\n" + S["fix_extra"][:12000]) if S.get("fix_extra") else ""

# ---------------------------------------------------------------- decide: the ONE close rule (only time closes a unit)
def settle_in_place(g, gates, S, u):
    """No wall for another attempt: the unit settles where it is - done (B with every gate passing), gap (provenance verified by its last full
    audit: its data flow with the unmet rows stated), gap_unaudited (a valid handoff whose provenance no audit verified), else failed. A reopened
    unit returns to done."""
    if S.get("reopened"):
        return "done", "reopen_unfinished"
    if S.get("cp_c"):   # the latest look (a checkpoint) found a defect in the current data: no audit verified them
        return ("gap", "gap_unaudited_checkpoint") if u.get("handoff_valid_at") else ("failed", "no_time")
    gates = gates or S.get("last_gates")
    if g == "B" and _g123_pass(gates):
        return "done", "b_all_pass_no_time"
    if (gates or {}).get("G1") == "pass":
        return "gap", "gap_no_time"
    if (gates or {}).get("G1") == "hit":   # untraceable data are never passed on as a gap
        return "failed", "g1_no_time"
    if u.get("handoff_valid_at"):
        return "gap", "gap_unaudited"
    return "failed", "no_time"

def _deliv_sig(u):
    """[files, bytes, newest mtime] over everything the unit's planned deliverables name (a pattern counts its matches, as the mech check expands
    it) - the B loop guard's "new data"."""
    n = tot = newest = 0
    for d in (u.get("deliverables") or []):
        real = _ws_path(d).rstrip("/")
        for p in (_pattern_hits(real) or [real]):
            q = _quick_sig(p)
            if not q:
                continue
            if len(q) == 3:
                n, tot, newest = n + q[0], tot + q[1], max(newest, q[2])
            else:
                n, tot, newest = n + 1, tot + q[0], max(newest, q[1])
    return [n, tot, newest]

def decide(g, S, gates, u):
    """-> (action, why). A -> done; D -> failed (task-book grounds). B -> fix in place while LAST_ACT_S is usable (a budget note when the fix is
    longer); the same gate hit standing B_SAME_HIT_MAX rounds in a row with no new data is handled as a C. C -> scouting + a fresh attempt while
    SCOUT_NEED_S is usable ('cpath'), else a fix in place while LAST_ACT_S is usable ('fix_c'). A reopened unit is never archived (its C is fixed
    in place). Otherwise the unit settles in place."""
    ul = usable_left()
    if g == "A":
        return "done", ("reaudit_A" if S.get("reopened") else "A")
    if g == "D":
        return ("done", "reopen_D_noted") if S.get("reopened") else ("failed", "D")
    if g == "B":
        hit = tuple(k for k in ("G1", "G2", "G3") if (gates or {}).get(k) == "hit")
        sig = _deliv_sig(u)   # "new data" = a planned deliverable changed (bookkeeping excluded)
        if hit and hit == S.get("b_hit") and sig == S.get("b_sig"):
            S["b_hit_n"] += 1
        else:
            S["b_hit"], S["b_hit_n"], S["b_sig"] = (hit or None), (1 if hit else 0), sig
        if not (hit and S["b_hit_n"] >= B_SAME_HIT_MAX):
            return ("fix", "B") if ul >= LAST_ACT_S else settle_in_place(g, gates, S, u)
        S["b_hit"], S["b_hit_n"] = None, 0
        g = "C"
    if S.get("reopened"):
        return ("fix_c", "reopen_C_in_place") if ul >= LAST_ACT_S else settle_in_place(g, gates, S, u)
    if scouting_due(u):
        return "cpath", "C"
    if ul >= LAST_ACT_S:
        return "fix_c", "C_late"
    return settle_in_place(g, gates, S, u)

# ---------------------------------------------------------------- the unit's life cycle (one thread per unit) - an explicit state machine
def _grant(uid, u, grant):
    return grant if grant is not None else POOL.acquire(uid, u, first=False)

def _budget_note(S, u):
    """The one budget note (fix rounds and fresh attempts alike): the critic's estimate exceeds the usable wall."""
    need = float(S.get("est") or 0) * 60
    if not math.isfinite(need) or need <= usable_left():   # a non-finite estimate is no estimate
        return ""
    return "\n\n" + BUDGET_NOTE.format(est=int(need // 60), spare=int(usable_left() // 60), knobs=_scale_hint(u)).strip()

def _mark_best(u, g, gates):
    """The unit's best validated round so far: the latest audit with G1 and G2 passing (grade A > B > C)."""
    if not (gates and gates.get("G1") == "pass" and gates.get("G2") == "pass" and g in ("A", "B", "C")):
        return
    rank = {"A": 3, "B": 2, "C": 1}
    b = u.get("_best") or {}
    if rank[g] >= rank.get(b.get("grade"), 0):
        u["_best"] = {"round": int(u.get("restarts") or 0), "grade": g, "t": int(time.time()), "dir": "/workspace/%s" % u["id"]}

def unit_worker(u, grant, start="exec"):
    """exec -> HANDOFF: mech -> wait on a live job | audit;  CUT: continue (a checkpoint when due, or when a finished job's verification was cut)
    -> decide -> fix in place / scouted fresh attempt / settle. start="reaudit": a done unit reopened for a changed input begins with a delta
    audit of the change and is never archived. Outcomes: done / gap / failed / flushed (a reopened unit returns to done)."""
    uid = u["id"]
    reopened = start == "reaudit"
    S = {"mode": "fresh", "extra": None, "sid": None, "rounds": 0, "mechs": 0, "nohand": 0, "doa": 0, "infra": 0, "est": None, "last_full_b": False,
         "last_gates": None, "events": set(), "restart": None, "why_cont": "", "b_hit": None, "b_hit_n": 0, "b_sig": None, "reopened": reopened,
         "t_call": None}
    prev_grade = RUN["grades"].get(uid)
    outcome, reason, g, gates = "failed", "thread_error", None, None
    job, cp_reason = None, None
    step = "audit_reopen" if reopened else "exec"
    LAST_LOOK.setdefault(uid, time.time())
    if not reopened:
        try:
            record_inputs(u)   # the consumed inputs' fingerprints at launch (hashing outside the scheduler's lock)
        except Exception as e:
            log("%s: input fingerprints failed: %s" % (uid, e))
    def flushed():
        return ("done", "reopen_override") if reopened else ("flushed", "override")
    try:
        while True:   # an orchestrator fault inside the unit's loop is never charged to the unit - logged, then the unit continues (twice at most)
            try:
                while True:
                    if OVERRIDE.is_set():
                        outcome, reason = flushed()
                        break
                    if step == "exec":
                        grant = _grant(uid, u, grant)
                        if S["mode"] == "fix":   # the round's instructions stay in force through its continuations until the next verdict
                            S["fix_extra"] = S.get("extra") or ""
                        tag, prompt, resume = _exec_call_spec(u, S)
                        was_resume = S["mode"] == "resume"
                        sig0 = _handoff_sig(uid)
                        fix_t = int(min(EXEC_SLICE_S, max(BFIX_MIN_S, 2 * float(S.get("est") or 0) * 60)))
                        exec_t = fix_t if S["mode"] == "fix" else EXEC_SLICE_S
                        sliced = exec_t < remaining() - report_reserve_s() - CLAMP_MARGIN_S   # every executor call: a cut is continued, never audited
                        r = run_call(prompt, exec_t, tag, resume_sid=(S["sid"] if resume else None), wrapup=None,
                                     grant=grant, cwd=unit_dir(uid), slice_ext=(uid if sliced else None))   # an unsliced call ends at the override (flush)
                        S["t_call"] = r.get("t0")
                        S["sid"] = r.get("sid") or S["sid"]
                        EXEC_SIDS[uid] = S["sid"]
                        kind = call_outcome(uid, r, sig0)
                        ledger({"kind": "exec", "unit": uid, "mode": S["mode"], "round": S["rounds"], "tokens": r.get("tokens"), "rc": r.get("rc"),
                                "interrupted": r.get("interrupted"), "dur": int((r.get("t1") or time.time()) - (r.get("t0") or time.time())), "outcome": kind})
                        if kind == "INTERRUPTED":
                            outcome, reason = flushed()
                            break
                        if kind == "INFRA":
                            S["infra"] += 1
                            if INFRA["dead"]:
                                outcome, reason = flushed()
                                break
                            if S["mode"] == "fresh-restart":   # the retry re-issues the fresh attempt's prompt
                                S["mode"] = "restart"
                            ledger({"kind": "infra_unit_hold", "unit": uid, "cycle": S["infra"]})
                            OVERRIDE.wait(min(600, max(5, INFRA_PROBE_S // 6)))
                            continue
                        S["infra"] = 0
                        if kind != "HANDOFF" and (r.get("t1") or 0) - (r.get("t0") or 0) < 60:
                            S["spin"] = S.get("spin", 0) + 1
                            if S["spin"] >= SPIN_N:
                                ledger({"kind": "spin_hold", "unit": uid, "calls": S["spin"], "hold_s": SPIN_HOLD_S})
                                log("%s: %d executor calls in a row ended within a minute without a handoff -> hold %d s" % (uid, S["spin"], SPIN_HOLD_S))
                                S["spin"] = 0
                                OVERRIDE.wait(SPIN_HOLD_S)
                                if OVERRIDE.is_set():
                                    outcome, reason = flushed()
                                    break
                        else:
                            S["spin"] = 0
                        if not _live_unit_pids(uid):
                            POOL.release(uid)
                            grant = None
                        if kind in ("CUT", "CUT_NOHAND"):
                            S["nohand"] = S["nohand"] + 1 if kind == "CUT_NOHAND" else 0
                            S["events"] = {"slice_cut"}
                            ledger({"kind": "slice", "unit": uid, "mode": S["mode"], "rc": r.get("rc"), "outcome": kind})
                            if was_resume and usable_left() >= LAST_ACT_S:   # the job's results are on disk: look at them now, never a blind continuation
                                step, cp_reason, job = "check", "after_job", None
                                continue
                            cp_reason = checkpoint_due(uid)
                            if cp_reason:
                                step, job = "check", current_job(uid)
                                continue
                            if S["nohand"] >= NOHAND_MAX and _handoff_sig(uid):
                                log("%s: %d turns in a row ended without a new handoff -> the audit decides on what exists" % (uid, S["nohand"]))
                                S["nohand"] = 0
                                step = "mech"
                                continue
                            S["mode"], S["why_cont"] = "continue", _cut_why(kind, r).replace("{uid}", uid) + _fix_carry(S)
                            continue
                        S["nohand"] = 0
                        step = "mech"
                        continue
                    if step == "mech":
                        mech = mech_check(uid, u, S.get("t_call"))
                        if mech.get("all_ok"):
                            u["handoff_valid_at"] = time.time()
                        else:
                            u.pop("handoff_valid_at", None)
                        checkpoint()
                        job = current_job(uid, implicit=False)
                        if job and not mech.get("handoff_errors"):
                            step = "wait"
                            continue
                        if mech.get("stopped"):
                            reap_leftovers(uid)   # the executor asked for a verdict: nothing unregistered keeps the unit waiting
                            step = "audit"
                            continue
                        if not mech.get("all_ok"):
                            S["mechs"] += 1
                            if S["mechs"] <= MECH_MAX:
                                machine_critic(uid, mech, "B")
                                S["mode"], S["extra"], S["events"], S["est"] = "fix", FIX_PROMPT.format(uid=uid, grade="B (mechanical check)", fixes=extract_fixes(uid) + mech_notes(mech, "\n\n")), mech_events(mech), 10
                                step = "exec"
                                continue
                            log("%s: %d mechanical fix rounds without a valid handoff -> the audit decides" % (uid, S["mechs"]))
                            step = "audit"
                            continue
                        live = _live_unit_pids(uid)
                        if live and _data_grew(unit_dir(uid), time.time() - 900):
                            job = current_job(uid)   # an unregistered computation still writes data: waited on (the checkpoint applies)
                            step = "wait" if job else "audit"
                            continue
                        if live:
                            reap_leftovers(uid)
                        step = "audit"
                        continue
                    if step == "wait":
                        how, secs, cp = wait_job(uid, u, job)
                        if how == "override":   # the job keeps the executors' flush window to write its last points
                            t_end = (OVERRIDE_T0["t"] or time.time()) + FLUSH_WINDOW - 180
                            while time.time() < t_end and not job_ended(uid, job):
                                time.sleep(max(1, min(20, WAIT_TICK)))
                            outcome, reason = flushed()
                            break
                        if how == "check":
                            step, cp_reason = "check", cp
                            continue
                        if how in ("exited", "stalled") and secs < 300 and not job.get("implicit"):
                            S["doa"] += 1
                        else:
                            S["doa"] = 0
                        if S["doa"] >= 2 and usable_left() >= LAST_ACT_S:   # two registrations dead on arrival: a look instead of a third resume
                            S["doa"] = 0
                            step, cp_reason, job = "check", "after_job", None
                            continue
                        S["mode"], S["extra"] = "resume", resume_text(uid, job, how, secs)
                        S["events"] = {"stalled"} if how == "stalled" else ({"orphan"} if how == "orphan" else set())
                        job = None
                        step = "exec"
                        continue
                    if step == "check":
                        vg = run_checkpoint(uid, u, cp_reason, job)
                        S["events"] = set()
                        if vg in ("W", "C") and job is not None and job_ended(uid, job):
                            ledger({"kind": "checkpoint_superseded", "unit": uid, "grade": vg})
                            vg = "ended"   # the job finished during the look: its complete results get a resume and a full audit
                        if vg == "D":   # task-book grounds are ruled by a full audit (never a delta); a running job is kept for a possible scouting
                            S["last_full_b"], S["d_job"] = False, (job if (job and not job_ended(uid, job)) else None)
                            step = "audit"
                            continue
                        if vg == "W":
                            job = job if (job and not job_ended(uid, job)) else current_job(uid)
                            if job:
                                step = "wait"
                                continue
                            S["mode"], S["why_cont"] = "continue", "the checkpoint found the unit on track - continue the plan and hand off." + _fix_carry(S)
                            step = "exec"
                            continue
                        if vg in ("B", "ended"):
                            fp = parse_fix_plan(uid) or {}
                            S["est"] = fp.get("est_min")
                            if vg == "ended" or (job is not None and job_ended(uid, job)):
                                S["mode"] = "resume"
                                S["extra"] = resume_text(uid, job, "marker" if os.path.exists(_ws_path(job["done_marker"])) else "exited", 0) + (
                                    "\n\nCHECKPOINT NOTES (taken while the job was finishing - check them against the complete results):\n" + extract_fixes(uid)[:3000])
                            else:
                                S["mode"], S["extra"] = "fix", FIX_PROMPT.format(uid=uid, grade="B (checkpoint)", fixes=extract_fixes(uid)) + _budget_note(S, u)
                            S["last_full_b"] = False
                            job = job if (job and not job_ended(uid, job)) else None
                            step = "exec"
                            continue
                        g, gates = "C", None
                        S["c_job"] = job if (job and not job_ended(uid, job)) else None
                        S["cp_c"] = True   # the latest look is a checkpoint C: at the end the unit's current data count as unaudited
                        step = "decide"
                        continue
                    if step in ("audit", "audit_reopen"):
                        if step == "audit_reopen":
                            notice = ((u.get("reopen_why") or "") + "\n" + change_notice(u)).strip()
                            g = run_critic(uid, delta=True, notice=notice, why_delta="it was graded done, and since then an input it consumed changed (the notice below). "
                                           "Verify whether its results depend on the change; its data stay in place.")
                        else:
                            g = run_critic(uid, delta=(S["last_full_b"] and (S["mode"] == "fix" or bool(S.get("fix_extra")))))
                            if g is None and not OVERRIDE.is_set():
                                g = run_critic(uid)
                        if g is None and OVERRIDE.is_set():
                            outcome, reason = flushed()
                            break
                        if g is None:
                            g = machine_critic(uid, {"fails": [NO_VERDICT_FIX]}, "B")
                            gates = None
                        else:
                            gates = parse_gates(uid)
                            S["last_gates"] = gates
                            _mark_best(u, g, gates)
                        S["last_full_b"] = bool(g == "B" and _g13_pass(gates))
                        S["c_job"], S["cp_c"], S["fix_extra"] = S.pop("d_job", None), False, ""
                        step = "decide"
                        continue
                    if step == "decide":
                        fp = parse_fix_plan(uid) or {}
                        S["est"] = fp.get("est_min")
                        action, why = decide(g, S, gates, u)
                        if SMOKE_FORCE_C and not RUN.get("smoke_forced") and not reopened and g in ("A", "B") and action in ("done", "fix"):
                            RUN["smoke_forced"] = True
                            ensure_residual(uid, "smoke test: grade %s handled as C to exercise the scouting" % g)
                            ledger({"kind": "smoke_forced_c", "unit": uid, "grade_was": g, "action_was": action})
                            g, action, why = "C", ("cpath" if scouting_due(u) else "fix_c"), "C"
                        ledger({"kind": "fix_plan", "unit": uid, "grade": g, "est_min": S["est"], "round": S["rounds"], "mechs": S["mechs"], "action": action,
                                "reason": why, "usable_s": int(usable_left()), "remaining_s": int(remaining()), "reopened": reopened})
                        if override_hold(u, g, action, why):
                            outcome, reason = flushed()
                            break
                        if action in ("done", "gap", "failed"):
                            outcome, reason = action, why
                            break
                        S["rounds"] += 1
                        if action == "fix":
                            S["mode"], S["extra"], S["events"] = "fix", FIX_PROMPT.format(uid=uid, grade=g, fixes=extract_fixes(uid)) + _budget_note(S, u), set()
                            step = "exec"
                            continue
                        if action == "fix_c":
                            S["mode"] = "fix"
                            S["extra"] = FIX_PROMPT.format(uid=uid, grade="C - fixed IN PLACE (%s): address what the residual names, keep the data that hold" % why,
                                                           fixes=(read(os.path.join(unit_dir(uid), "residual.md"))[:5000] or extract_fixes(uid))) + _budget_note(S, u)
                            S["events"], S["last_full_b"] = {"restart"}, False
                            step = "exec"
                            continue
                        # cpath: scouting first (the unit's directory is read in place; a running job keeps running), then a fresh attempt only if one fits
                        cjob = S.pop("c_job", None)
                        if not cjob:
                            reap_leftovers(uid)
                            POOL.release(uid)   # nothing of the unit runs: the scouts take the unit's share (never counted twice)
                            grant = None
                        ensure_residual(uid, "grade C (round %d)" % S["rounds"])
                        sgrant = POOL.acquire(uid + "~scout", u, first=False)
                        try:
                            sc = scout_round(u, sgrant, cjob)
                        finally:
                            POOL.release(uid + "~scout")
                        if OVERRIDE.is_set():
                            outcome, reason = flushed()
                            break
                        scout_readings(uid, sc)   # before any archive: the evidence files are where the scouts saw them
                        if sc.get("winner") and usable_left() >= MIN_ATTEMPT_S + 600:
                            prov, pnote = _prov_restart(u, S["rounds"], g)
                            rinfo = restart_unit(u, S["rounds"], g, pnote, keep_deliverables=prov)
                            scout_seed(uid, sc)
                            rinfo["note"] = ((rinfo.get("note") or "") + " " + scout_note(uid, sc)).strip()
                            rinfo["note"] += _budget_note(S, u)
                            grant = _grant(uid, u, None)
                            S.update({"mode": "restart", "restart": rinfo, "sid": None, "last_full_b": False, "events": set(), "b_hit": None, "b_hit_n": 0,
                                      "last_gates": None, "cp_c": False, "fix_extra": ""})
                            job = None
                            step = "exec"
                            continue
                        if sc.get("winner"):   # no fresh attempt fits: the winner's route is applied in place (its files seeded, its readings propagated)
                            scout_seed(uid, sc)
                            snote = scout_note(uid, sc)
                        else:
                            snote = sc.get("note") or ""
                        if usable_left() < LAST_ACT_S:
                            outcome, reason = settle_in_place(g, gates, S, u)
                            break
                        running = ("\n\nThe unit's job (pid %s) is still running: keep it only if the route above still needs its output, else stop it."
                                   % cjob.get("pid")) if (cjob and not job_ended(uid, cjob)) else ""
                        S["mode"] = "fix"
                        S["extra"] = FIX_PROMPT.format(uid=uid, grade="C - fixed IN PLACE (%s)" % ("the scouted route; no fresh attempt fits" if sc.get("winner") else "no scouted route"),
                                                       fixes=(read(os.path.join(unit_dir(uid), "residual.md"))[:5000] or extract_fixes(uid))) + (
                                                       ("\n\n" + snote) if snote else "") + running + _budget_note(S, u)
                        S["events"], S["last_full_b"] = {"restart"}, False
                        job = None
                        step = "exec"
                        continue
                break
            except Exception as e:
                import traceback
                log("unit thread %s crashed: %s\n%s" % (uid, e, traceback.format_exc()[-1500:]))
                S["faults"] = S.get("faults", 0) + 1
                rec = not reopened and S["faults"] <= 2 and not OVERRIDE.is_set() and usable_left() >= LAST_ACT_S
                ledger({"kind": "unit_thread_error", "unit": uid, "error": str(e)[:300], "recovered": rec, "n": S["faults"]})
                if rec:
                    try:
                        if POOL:
                            POOL.release(uid + "~scout")
                    except Exception:
                        pass
                    log("%s: orchestrator fault %d - the unit continues (a fault is never charged to the unit)" % (uid, S["faults"]))
                    S["mode"], S["why_cont"], S["events"] = "continue", FAULT_WHY + _fix_carry(S), set()
                    job, cp_reason, step = None, None, "exec"
                    continue
                if reopened:
                    outcome, reason = "done", "reopen_thread_error"
                elif u.get("handoff_valid_at") and (S.get("last_gates") or {}).get("G1") == "pass" and not S.get("cp_c"):
                    outcome, reason = "gap", "thread_error_kept"
                else:
                    outcome, reason = "failed", "thread_error"
                g = g or "U"
                break
    finally:
        try:
            if POOL:
                POOL.release(uid)
                POOL.release(uid + "~scout")
        finally:
            settle(u, outcome, reason, (prev_grade if (reopened and outcome == "done" and reason != "reaudit_A") else g), S["rounds"])

def _exec_call_spec(u, S):
    """(tag, prompt, resume?) of the next executor-family call from the unit's state."""
    uid = u["id"]
    m = S["mode"]
    if m == "fresh":
        return "exec_%s" % uid, exec_prompt(u), False
    if m == "restart":
        S["mode"] = "fresh-restart"
        return "restart_%s" % uid, exec_prompt(u, restart=S["restart"]), False
    if m == "continue":
        return "cont_%s" % uid, CONTINUE_PROMPT.format(uid=uid, why=S.get("why_cont") or "", notes=_exec_notes(u)) + bank_round_block(uid, S.get("events") or {"slice_cut"}, cite=bool(S.get("fix_extra"))), True
    if m == "resume":
        return "resume_%s" % uid, (S.get("extra") or "") + _exec_notes(u) + bank_round_block(uid, S.get("events") or set(), cite=False), True
    return "fix_%s" % uid, (S.get("extra") or "") + _exec_notes(u) + bank_round_block(uid, S.get("events") or set(), cite=True), True

# ---------------------------------------------------------------- the scheduler (main thread): launches, reopens, the branch replan
PLAN_KEYS = ("id", "type", "goal", "deliverables", "done_criteria", "depends_on", "needs", "cores", "mem_gb", "alloc_min", "scale_knobs",
             "report_cost_min", "notes")
def launch_unit(u, start="exec"):
    """Scheduler side: grant + directory + spec + input fingerprints + thread. Caller holds STATE_LOCK."""
    uid = u["id"]
    th0 = THREADS.get(uid)
    if th0 is not None and th0.is_alive():   # one thread per unit, always (a replan or a reopen never starts a second one)
        return False
    if start == "exec":
        waited = time.time() - float(u.get("ready_since") or time.time())
        g = POOL.acquire(uid, u, waited_s=waited, first=True)
        if g is None:
            return False
    else:
        g = None
    u["status"], u["t_launch"] = "running", time.time()
    u.pop("t_settle", None)
    if start == "exec":
        write_spec(u)
        prov = provisional_deps(u)
        for d in prov:
            du_ = unit_by_id(d)
            if du_ is not None:
                du_["released_deps"] = True
    else:
        prov = {}
    running = [x.get("id") for x in RUN["plan"] if x.get("status") == "running" and x.get("id") != uid]
    ledger({"kind": "launch", "unit": uid, "type": u.get("type"), "dir": "/workspace/%s/" % uid, "cores": (g or {}).get("cores"), "mem_gb": (g or {}).get("mem_gb"),
            "provisional": prov, "depends_on": list(u.get("depends_on") or []), "concurrent_with": running,
            "pool_used": list(POOL.used()), "remaining_s": int(remaining()), "start": start})
    log("LAUNCH %s (%s%s) in /workspace/%s/%s%s" % (uid, u.get("type"), "" if start == "exec" else ", REOPENED for a delta audit", uid,
        (" grant %dc/%dGB" % (g["cores"], g["mem_gb"])) if g else "", (" | running: %s" % ",".join(running)) if running else ""))
    LAST_LOOK[uid] = time.time()
    th = threading.Thread(target=unit_worker, args=(u, g, start), name="unit-%s" % uid, daemon=True)
    THREADS[uid] = th
    th.start()
    return True

def reblock_pending(plan):
    """A pending unit whose dependency retired (failed / blocked) while the planner ran would wait forever - it is blocked."""
    st = dict((x.get("id"), x.get("status")) for x in plan if isinstance(x, dict))
    out, changed = [], True
    while changed:
        changed = False
        for x in plan:
            if isinstance(x, dict) and not x.get("status") and x.get("type") != "render":
                bad = [d for d in (x.get("depends_on") or []) if st.get(d) in ("failed", "blocked")]
                if bad:
                    x["status"], x["blocked_by"] = "blocked", bad[0]
                    st[x.get("id")] = "blocked"
                    out.append(x.get("id"))
                    changed = True
                    ledger({"kind": "settle", "unit": x.get("id"), "status": "blocked", "reason": "upstream %s retired during the replan" % bad[0], "upstream": bad[0]})
    return out


def do_replan(req):
    """ONE planner call revises the branch of a retired unit while everything else keeps running. Done units and their
    directories are final; running units keep their live objects; the retired unit stays in the plan as history (id retired, directory kept
    for reference); blocked units named in the new plan become pending again; units the plan dropped are gone."""
    with STATE_LOCK:
        checkpoint()
        snapshot = json.loads(json.dumps(RUN["plan"]))
    newplan = get_plan(replan=req, old_plan=snapshot)
    if not newplan:
        ledger({"kind": "replan_failed", "unit": req["uid"], "blocked": req.get("blocked")})
        log("replan after %s produced no valid plan - the branch stays blocked: %s" % (req["uid"], req.get("blocked") or "-"))
        return False
    with STATE_LOCK:
        live = dict((x.get("id"), x) for x in RUN["plan"] if isinstance(x, dict))
        for i, nu in enumerate(newplan):
            ou = live.get(nu.get("id"))
            if ou is not None and ou.get("status") in ("done", "running") + HISTORY:
                newplan[i] = ou   # keep object identity: a running thread updates this dict
                continue
            for k in [k for k in list(nu) if k not in PLAN_KEYS]:   # a new or pending unit carries only planner keys (no copied orchestrator state)
                nu.pop(k, None)
            RUN["grades"].pop(nu.get("id"), None)
            while nu.get("id") in RUN["failed"]:
                RUN["failed"].remove(nu.get("id"))
        for ou in RUN["plan"]:   # a dropped retired unit stays in the plan as history
            if isinstance(ou, dict) and ou.get("status") in HISTORY and ou.get("id") not in [x.get("id") for x in newplan]:
                newplan.insert(0, ou)
        reblock_pending(newplan)
        RUN["plan"] = newplan
        ledger({"kind": "replan_applied", "unit": req["uid"], "units": [x.get("id") for x in newplan],
                "pending": [x.get("id") for x in newplan if not x.get("status") and x.get("type") != "render"],
                "running": [x.get("id") for x in newplan if x.get("status") == "running"], "done": [x.get("id") for x in newplan if x.get("status") == "done"]})
        log("branch replan applied: %s" % [x.get("id") + ("[%s]" % x["status"] if x.get("status") else "") for x in newplan])
        SCHED_CV.notify_all()
    checkpoint()
    return True

def _reopen_due(u):
    """A done produce unit flagged by propagation, with the wall for a delta audit and a fix, not reopened too often."""
    return (u.get("status") == "done" and u.get("reopen") and u.get("type") == "produce" and not OVERRIDE.is_set()
            and usable_left() >= REOPEN_MIN_S and int(u.get("reopens") or 0) < REOPEN_MAX)

def schedule_loop():
    """DAG scheduler (main thread). Returns 'normal' when every non-render unit is terminal (and no reopen is due), 'override' when the
    override fired."""
    while True:
        with SCHED_CV:
            for uid, th in list(THREADS.items()):
                if not th.is_alive():
                    THREADS.pop(uid, None)
            if OVERRIDE.is_set():
                return "override"
            req = RUN.pop("replan_req", None)
        if req:
            do_replan(req)
            continue
        with SCHED_CV:
            plan = RUN["plan"]
            others = [u for u in plan if isinstance(u, dict) and u.get("type") != "render"]
            for u in others:
                if u.get("status") == "done" and u.get("reopen") and u["id"] not in THREADS:
                    if _reopen_due(u):
                        u["reopens"] = int(u.get("reopens") or 0) + 1
                        u["reopen_why"] = u.pop("reopen").get("why")
                        ledger({"kind": "reopen", "unit": u["id"], "why": str(u["reopen_why"])[:300], "n": u["reopens"]})
                        launch_unit(u, start="reaudit")
                    else:
                        ledger({"kind": "reopen_skipped", "unit": u["id"], "why": str(u.pop("reopen").get("why"))[:200],
                                "usable_s": int(usable_left()), "reopens": int(u.get("reopens") or 0)})
            if all(u.get("status") in TERMINAL for u in others) and not THREADS:
                return "normal"
            for u in others:
                if u.get("status") not in ("running",) + TERMINAL and deps_done(u) and not u.get("ready_since"):
                    u["ready_since"] = time.time()
            ready = [u for u in others if u.get("status") not in ("running",) + TERMINAL and deps_done(u)]
            ready.sort(key=lambda x: float(x.get("ready_since") or 0))
            if not any([launch_unit(u) for u in ready]):
                SCHED_CV.wait(SCHED_TICK)

# ---------------------------------------------------------------- the override (the single time trigger) and the live clock
OVERRIDE_T0 = {"t": None}

def fire_override(reason="wall"):
    """Idempotent. Executors are told to flush (their dsh parent stops, their computations keep writing for FLUSH_WINDOW); critics, planners and
    scouts are stopped."""
    if OVERRIDE.is_set():
        return
    OVERRIDE.set()
    OVERRIDE_T0["t"] = time.time()
    with CALL_LOCK:
        active = [dict((k, v) for k, v in c.items() if k != "p") for c in ACTIVE_CALLS.values()]
    pending = "(state busy)"
    if STATE_LOCK.acquire(timeout=5):   # the trigger never waits on a busy scheduler
        try:
            pending = [u.get("id") for u in RUN["plan"] if isinstance(u, dict) and u.get("status") not in TERMINAL and u.get("type") != "render"]
        finally:
            STATE_LOCK.release()
    ledger({"kind": "override", "reason": reason, "remaining_s": int(remaining()), "report_cost_min": report_cost_min(), "flush_window_s": FLUSH_WINDOW,
            "active_calls": [c["tag"] for c in active], "unsettled": pending})
    log("OVERRIDE (%s): remaining %dm, report cost %dm -> report mode; flushing %s" % (reason, remaining() // 60, report_cost_min(), pending or "-"))
    ledger({"kind": "flush", "units": pending})
    interrupt_calls(lambda c: c.get("role") == "exec", "flush", "parent")
    interrupt_calls(lambda c: c.get("role") in ("critic", "plan", "scout"), "override", "tree")
    if STATE_LOCK.acquire(timeout=5):
        try:
            SCHED_CV.notify_all()
        finally:
            STATE_LOCK.release()

def write_clock():
    """/workspace/_pece/clock.json - the live clock every executor can `cat` (spare_s = usable_left, the one usable-time figure)."""
    try:
        units = "(state busy)"
        if STATE_LOCK.acquire(timeout=5):   # the clock never waits on a busy scheduler
            try:
                units = dict((x.get("id"), {"status": x.get("status"), "launched_at": int(x.get("t_launch") or 0),
                                            "used_s": int(time.time() - x["t_launch"]) if x.get("t_launch") and x.get("status") == "running" else None,
                                            "waiting": bool(x.get("waiting"))})
                             for x in RUN["plan"] if isinstance(x, dict) and x.get("t_launch"))
            finally:
                STATE_LOCK.release()
        c = {"ts": int(time.time()), "clock": now(), "wall_s": WALL, "elapsed_s": int(time.time() - T0), "remaining_s": int(remaining()),
             "report_reserve_s": int(report_reserve_s()), "spare_s": int(max(0, usable_left())), "override": OVERRIDE.is_set(),
             "note": "spare_s = wall left for computation before the run wraps up; a run longer than spare_s cannot finish", "units": units}
        _atomic_json_dump(c, os.path.join(PD, "clock.json"))
    except Exception as e:
        log("clock.json write failed: %s" % e)

def override_thread():
    write_clock()
    while not STOP.is_set():
        STOP.wait(OVERRIDE_TICK)
        if STOP.is_set() or REPORT["started"]:
            return
        if override_due():   # checked first: nothing on this thread may delay the trigger
            try:
                fire_override("wall")
            except Exception as e:
                log("override handler error: %s" % e)
            write_clock()
            return
        write_clock()

def flush_wait():
    """After the override: up to FLUSH_WINDOW (from the override instant) for the flushing threads to settle, then move on regardless."""
    t_end = (OVERRIDE_T0["t"] or time.time()) + FLUSH_WINDOW
    for th in list(THREADS.values()):
        th.join(max(0, t_end - time.time()))
    still = [uid for uid, th in THREADS.items() if th.is_alive()]
    ledger({"kind": "flush_done", "waited_s": int(time.time() - (OVERRIDE_T0["t"] or time.time())), "still_running": still})
    for uid in still:   # nothing of an unsettled unit runs into the report
        try:
            reap_leftovers(uid)
        except Exception:
            pass
    if still:
        log("flush window over; still running (their processes stopped): %s" % still)

# ---------------------------------------------------------------- the report agent (the render unit)
def unit_status_table():
    with STATE_LOCK:
        plan = list(RUN["plan"])
        grades = dict(RUN["grades"])
    L = ["UNIT STATUS TABLE (orchestrator truth; id | type | status | critic grade | directory | notes):"]
    for u in plan:
        if not isinstance(u, dict):
            continue
        uid = u.get("id")
        st = u.get("status") or "not started"
        d = "/workspace/%s/" % uid
        notes = []
        if st == "blocked":
            notes.append("blocked: upstream %s retired - never ran, no data" % u.get("blocked_by"))
        elif st == "failed":
            notes.append("retired: its data were not verified by an audit - usable only as the rules say (plotted as unaudited, listed under LIMITATIONS); residual.md in its directory")
        elif st == "flushed":
            notes.append("flushed at the override (partial, unaudited)")
        elif st == "running":
            notes.append("still running")
        if st == "done" and u.get("gap"):
            notes.append("DONE WITH GAP: %s; unmet: %s - plot its data as it is and state the miss; never fill, rescale or calibrate it"
                         % (("its last look (a checkpoint) found a defect in its current data - its critic_report.md says which; plot it marked unaudited"
                             if u.get("settle_reason") == "gap_unaudited_checkpoint" else "its provenance was NOT verified by an audit - plot it marked unaudited")
                            if u.get("gap_unaudited") else "provenance verified",
                            str(u.get("gap_note", ""))[:300]))
        b = u.get("_best") or {}
        if b.get("dir") and (st != "done" or u.get("gap")):
            if b["dir"] != "/workspace/%s" % uid:
                notes.append("BEST VALIDATED ROUND: %s/ (grade %s, G1 and G2 passed) - prefer its data where the live directory is incomplete or unaudited"
                             % (b["dir"], b.get("grade")))
            else:
                notes.append("LAST VALIDATED STATE: this directory passed G1 and G2 at its audit of %s (grade %s); files written after that audit are unaudited"
                             % (time.strftime("%H:%M", time.localtime(b.get("t") or 0)), b.get("grade")))
        if st == "flushed" and u.get("flush_note"):
            notes.append(u["flush_note"][:400])
        if u.get("restarts"):
            notes.append("restarted %d time(s); earlier rounds: %s" % (u["restarts"], ", ".join(u.get("archives") or [])))
        rows = owned_rows(uid)
        if rows:
            notes.append("owns required rows %s" % ", ".join(str(r.get("id")) for r in rows))
        try:
            mj = json.load(open(os.path.join(_ws_path(d), "mech.json")))
            notes.append("mech %d/%d deliverables OK%s" % (mj.get("n_deliv_ok", 0), mj.get("n_deliv", 0), (", stopped: %s" % str(mj.get("stopped"))[:120]) if mj.get("stopped") else ""))
        except Exception:
            pass
        for fn in ("handoff.json", "profile.json"):
            if os.path.exists(os.path.join(_ws_path(d), fn)):
                notes.append(fn)
        if str(u.get("settle_reason") or "").startswith("reopen") and u.get("settle_reason") != "reaudit_A":
            notes.append("REOPENED after an input change and not re-verified (%s) - its critic_report.md says what the change affects" % u["settle_reason"])
        L.append("  %s | %s | %s | %s | %s | %s" % (uid, u.get("type"), st, grades.get(uid, "-"), d, "; ".join(notes) or "-"))
    conf = RUN.get("reading_conflicts") or []
    if conf:
        L.append("READING CONFLICTS (a second change of an already-changed reading was refused - list them under CONFLICTS): "
                 + "; ".join("%s -> %s (evidence %s, by %s)" % (c.get("id"), c.get("reading"), c.get("evidence"), c.get("by")) for c in conf[:8]))
    return "\n".join(L)

def report_prompt(rid, mode, mode_note):
    with STATE_LOCK:
        done = [u.get("id") for u in RUN["plan"] if isinstance(u, dict) and u.get("status") == "done" and u.get("id") != rid]
        other = [u for u in RUN["plan"] if isinstance(u, dict) and u.get("status") in ("flushed", "failed") and u.get("type") != "render"]
    src = ["SOURCES - done units (verified; DONE WITH GAP units state their unmet rows):"]
    src += ["  %s -> /workspace/%s/ : read /workspace/%s/handoff.json first (%s)" % (d, d, d, _handoff_summary(d, 300)) for d in done] or ["  (none)"]
    if other:
        src.append("FLUSHED / RETIRED units (unaudited - usable only as the rules say):")
        src += ["  %s (%s) -> /workspace/%s/ (handoff.json %s)" % (u["id"], u.get("status"), u["id"], "present" if os.path.exists(os.path.join(unit_dir(u["id"]), "handoff.json")) else "missing") for u in other]
    return REPORT_PROMPT.format(mode=mode, uid=rid, mode_note=mode_note, status_table=unit_status_table(), sources="\n".join(src)) + bank_report_block()

def _report_t():
    """The report call leaves about 27 min before the wall, so a timeout still gets a real pens-down session."""
    want = max(FIN_T, report_cost_min() * 60 + 600)
    return int(max(600, min(want, remaining() - 1620)))

def root_copy(rid):
    """The final files are collected at /workspace/ root: copy report.md and reproduced_figure* from the render directory when
    the agent left them only there, or left a newer version there."""
    rd, n = unit_dir(rid), []
    for fn in sorted(os.listdir(rd)) if os.path.isdir(rd) else []:
        if fn == "report.md" or (fn.startswith("reproduced_figure") and fn.endswith((".png", ".pdf"))):
            src, dst = os.path.join(rd, fn), os.path.join(WS, fn)
            try:
                if os.path.isfile(src) and (not os.path.exists(dst) or os.path.getmtime(src) > os.path.getmtime(dst) + 1):
                    shutil.copy2(src, dst)
                    n.append(fn)
            except OSError as e:
                log("root copy of %s failed: %s" % (fn, e))
    if n:
        ledger({"kind": "root_copy", "unit": rid, "files": n})
        log("report agent left %s only in /workspace/%s/ -> copied to /workspace/" % (", ".join(n), rid))
    return n


def _render_critic(rid):
    """The render unit's audit - it runs after the override too (the report step is past it)."""
    return run_critic(rid, force=True) or run_critic(rid, force=True)

def run_report(mode):
    """The report agent executes the render unit in /workspace/render/, then its audit (normal and override mode) while the wall allows it: at
    most 3 verdict rounds, B fixed in place, C redone while the wall allows."""
    global POOL
    if POOL is None:   # the last-resort report after an early failure
        POOL = ResourcePool(NCPUS, MEM_GB)
    with STATE_LOCK:
        rend = next((u for u in RUN["plan"] if isinstance(u, dict) and u.get("type") == "render"), None)
        REPORT["started"], REPORT["reason"], REPORT["t"] = True, mode, int(time.time())
        rid = rend["id"] if rend else "render"
        rd = unit_dir(rid)
        os.makedirs(rd, exist_ok=True)
        if rend:
            rend["status"], rend["t_launch"] = "running", time.time()
            write_spec(rend)
    ledger({"kind": "report_start", "mode": mode, "unit": rid, "dir": "/workspace/%s/" % rid, "remaining_s": int(remaining()),
            "report_cost_min": report_cost_min(), "grades": dict(RUN["grades"]), "failed": list(RUN["failed"]),
            "blocked": [u.get("id") for u in RUN["plan"] if isinstance(u, dict) and u.get("status") == "blocked"],
            "flushed": [u.get("id") for u in RUN["plan"] if isinstance(u, dict) and u.get("status") == "flushed"]})
    log("REPORT AGENT (%s) on %s: remaining %dm" % (mode, rid, remaining() // 60))
    checkpoint()
    grant = (POOL.acquire(rid, rend, first=False) if rend else None) or POOL.acquire_free(rid, want=2)
    mode_note = REPORT_MODE_OVERRIDE if mode == "override" else REPORT_MODE_NORMAL
    t_r0 = time.time()
    try:
        r = run_call(report_prompt(rid, mode.upper(), mode_note), _report_t(), "report_%s" % rid, wrapup=WRAP_FIN, grant=grant, cwd=rd)
    finally:
        POOL.release(rid)
    sid = r["sid"]
    root_copy(rid)
    mech = mech_check(rid, rend, t_r0) if rend else None
    ledger({"kind": "report", "mode": mode, "unit": rid, "tokens": r["tokens"], "rc": r["rc"], "ok": deliverables_ok(), "handoff": os.path.exists(os.path.join(rd, "handoff.json"))})
    r2 = None
    if not os.path.exists(os.path.join(WS, "report.md")) and remaining() > 420 and not INFRA["dead"]:
        log("report.md still missing after the report agent -> pointed report-only retry")
        r2 = run_call("Write ONLY /workspace/report.md now, using the figures and data ALREADY on disk under /workspace: the task-book items F1..Fn one "
                      "by one (met / partial / missing, evidence file), the method actually implemented, the parameters used, the results compared to "
                      "the paper's target values, and an honest LIMITATIONS section. Do NOT compute anything and do NOT touch any other file. Then stop.",
                      max(240, min(1800, int(remaining() - 360))), "report_%s_only" % rid, resume_sid=sid, wrapup=WRAP_FIN, cwd=rd)
        root_copy(rid)
        ledger({"kind": "finalize_report", "tokens": r2["tokens"], "rc": r2["rc"], "ok": os.path.exists(os.path.join(WS, "report.md"))})
    if not os.path.exists(os.path.join(WS, "report.md")) and not INFRA["dead"]:
        if (r2 if r2 is not None else r).get("infra"):   # the last attempt decides: a backend that answered the retry is alive
            infra_dead("report_%s" % rid, "the report calls stay dead (0 tokens) in the report window")
        else:
            write_fallback_report(rid)
    g = None
    if rend and not INFRA["dead"] and remaining() > 1500:   # the render audit (normal and override mode alike) while the wall allows it
        rounds = 0
        while remaining() > 1500:
            if mech and not mech["all_ok"]:
                g = machine_critic(rid, mech)
            else:
                g = _render_critic(rid)
            fp = parse_fix_plan(rid) or {}
            est = float(fp.get("est_min") or 0)
            left = remaining() - 900
            action = ("done" if g == "A" else "keep" if (g in (None, "D") or rounds >= 3) else
                      "fix" if (g == "B" and left >= max(est * 60, 1200)) else "restart" if (g == "C" and left >= max(est * 60, 2700)) else "keep")
            ledger({"kind": "report_grade", "round": rounds, "grade": g, "action": action, "est_min": fp.get("est_min"), "remaining_s": int(remaining())})
            if action in ("done", "keep"):
                break
            rounds += 1
            grant = POOL.acquire(rid, rend, first=False) or POOL.acquire_free(rid, want=2)
            t_r0 = time.time()
            try:
                if action == "fix":
                    rf = run_call(FIX_PROMPT.format(uid=rid, grade=g, fixes=extract_fixes(rid)) + bank_round_block(rid), min(int(max(1200, 2 * est * 60)), FIN_T),
                                  "fix_%s" % rid, resume_sid=sid, wrapup=WRAP_FIN, grant=grant, cwd=rd)
                    sid = rf["sid"] or sid
                else:
                    rs = restart_unit(rend, rounds, g)
                    rf = run_call(report_prompt(rid, "NORMAL (RESTART after critic grade %s)" % g, REPORT_MODE_NORMAL + " The previous render (archived at %s/) "
                                                "was graded %s: read %s/residual.md and critic_report.md there first and fix every verified defect." % (rs["archive"], g, rs["archive"])),
                                  _report_t(), "restart_%s" % rid, wrapup=WRAP_FIN, grant=grant, cwd=rd)
                    sid = rf["sid"]
            finally:
                POOL.release(rid)
            root_copy(rid)
            mech = mech_check(rid, rend, t_r0)
        with STATE_LOCK:
            RUN["grades"][rid] = g or "U"
    elif rend:
        with STATE_LOCK:
            RUN["grades"].setdefault(rid, "U")
    with STATE_LOCK:
        if rend:
            rend["status"] = "done" if RUN["grades"].get(rid) in ("A", "B") else "failed"
    checkpoint()
    return g

def write_fallback_report(rid):
    """The report agent did not deliver and the backend answers: /workspace/report.md from the orchestrator's own records (said so first), so
    the episode never ends without a report."""
    figs = sorted(os.path.basename(p) for p in glob.glob(os.path.join(WS, "reproduced_figure*")))
    L = ["# Report (written by the orchestrator: the report agent did not deliver report.md)", "",
         "The figures and data below are what the run's units left on disk; nothing here was checked by the report agent.", "",
         "## Figures", ""] + (["- /workspace/%s" % f for f in figs] or ["- none rendered"]) + ["", "## Units", "", unit_status_table(), ""]
    for u in RUN["plan"]:
        if not isinstance(u, dict) or u.get("type") == "render":
            continue
        try:
            h = json.load(open(os.path.join(unit_dir(u["id"]), "handoff.json")))
        except Exception:
            continue
        if not isinstance(h, dict):
            continue
        L += ["### %s (%s)" % (u["id"], u.get("status")), "key numbers: %s" % json.dumps(h.get("key_numbers"), ensure_ascii=False)[:1500],
              "known limits: %s" % json.dumps(h.get("known_limits"), ensure_ascii=False)[:800], ""]
    try:
        with open(os.path.join(WS, "report.md"), "w") as f:
            f.write("\n".join(L) + "\n")
        ledger({"kind": "fallback_report", "unit": rid, "figures": figs})
        log("report.md written by the orchestrator (the report agent did not deliver)")
    except Exception as e:
        log("fallback report failed: %s" % e)

def build_digest():
    """Deterministic workflow summary: call timeline, billing, grade sequences, time by role, notable events."""
    events = []
    for line in read(os.path.join(PD, "ledger.jsonl")).splitlines():
        try:
            e = json.loads(line)
        except Exception:
            continue
        if isinstance(e, dict):   # the ledger lies in /workspace: a line an agent appended that is not an object is skipped
            events.append(e)
    calls = [e for e in events if e.get("kind") == "call"]
    L = ["# Episode digest - %s (paper %s)" % (RUN_ID, PAPER), "",
         "wall=%ds spent=%ds deliverables=%s calls=%d" %
         (WALL, int(time.time() - T0), deliverables_ok(), len(calls)), "",
         "## Call timeline (# | tag | minutes | tokens | rc)"]
    role_min = {}
    for i, c in enumerate(calls, 1):
        mins = c.get("dur", 0) / 60.0
        role = re.split(r"[_\d]", c["tag"], 1)[0]
        role_min[role] = role_min.get(role, 0) + mins
        L.append("%02d | %-24s | %5.1f | %8d | rc=%s%s" %
                 (i, c["tag"], mins, c.get("tokens") or 0, c.get("rc"), "  <-WRAPUP" if c["tag"].endswith("_wrapup") else ""))
    bl = [c for c in calls if c.get("usage")]
    if bl:
        tot = dict((k, sum((c["usage"] or {}).get(k, 0) for c in bl)) for k in ("input", "cached", "output", "reasoning"))
        L += ["", "## Usage (dsh session usage x RA3SR_RATES $/Mtok uncached %.3g / cached %.3g / output %.3g)" % RATES,
              "calls=%d uncached in=%d cached in=%d out=%d (reasoning inside: %d) cost=$%.2f"
              % (len(bl), tot["input"], tot["cached"], tot["output"], tot["reasoning"], sum(c.get("cost_usd") or 0 for c in bl)),
              "top calls by cost: " + ", ".join("%s $%.2f" % (c["tag"], c.get("cost_usd") or 0)
                                                 for c in sorted(bl, key=lambda c: -(c.get("cost_usd") or 0))[:5])]
    L += ["", "## Time by role (minutes)"] + ["%-10s %6.1f" % (k, v) for k, v in sorted(role_min.items(), key=lambda x: -x[1])]
    L += ["", "## Unit grade sequence"] + ["%s -> %s (%s%s)" % (e.get("unit"), e.get("grade"), e.get("by", "llm"), ", residual" if e.get("residual") else "")
                                          for e in events if e.get("kind") == "critic"]
    nk = ("finalize_report", "plan", "plan_invalid", "plan_minimal", "replan_trigger", "replan_applied", "replan_failed", "replan_cap", "d_rejected", "archive",
          "restart", "settle", "writes_outside_own_dir", "fix_plan", "override", "flush", "interrupt", "launch", "report", "report_start", "root_copy",
          "pool_shared", "infra_retry", "infra_call_dead", "infra_unit_dead", "infra_failure", "critic_skipped", "leftover_killed", "settle_reaped",
          "wait_start", "wait_end", "wait_check", "checkpoint", "scout_winner", "scout_fallback", "reading_change", "upstream_changed", "reopen",
          "reopen_skipped", "unit_gap", "critic_regrade", "requeue_refused")
    rs = [e for e in events if e.get("kind") == "report_start"]
    if rs:
        idle = float(rs[-1].get("remaining_s") or 0)
        L += ["", "idle wall at report start: %.1fh (%d%% of the %.1fh wall)" % (idle / 3600.0, int(100 * idle / max(WALL, 1)), WALL / 3600.0)]
    notable = [e for e in events if e.get("kind") in nk]
    if notable:
        L += ["", "## Notable events"] + ["%s %s %s" % (e["kind"], e.get("unit") or "", e.get("reason") or e.get("status") or e.get("tag") or e.get("dir") or e.get("units", ""))
                                        for e in notable]
    txt = "\n".join(L) + "\n"
    open(os.path.join(PD, "digest.md"), "w").write(txt)
    return txt


def deliverables_ok():
    """All figure files CLAUDE.md names explicitly + report.md, at /workspace/ root (where the pipeline collects them)."""
    required = set(re.findall(r"reproduced_figure[A-Za-z0-9_\-]*\.png", read(os.path.join(WS, "CLAUDE.md"))))
    figs_ok = all(os.path.exists(os.path.join(WS, f)) for f in required) if required else \
        any(f.startswith("reproduced_figure") and f.endswith(".png") for f in os.listdir(WS))
    return figs_ok and os.path.exists(os.path.join(WS, "report.md"))


def build_trace():
    """trace.py next to this file renders _pece/trace.json, timeline.html and timeline.txt from the ledger."""
    tp = os.path.join(os.path.dirname(os.path.abspath(__file__)), "trace.py")
    try:
        import importlib.util
        spec = importlib.util.spec_from_file_location("ra_trace", tp)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        out = mod.build(PD, plan_path=os.path.join(PD, "plan.json"))
        log("trace written: %s" % ", ".join(os.path.basename(x) for x in out))
        return out
    except Exception as e:
        log("trace generation failed (%s): %s" % (tp, e))
        return []

def epilogue():
    """token_usage.json, digest.md, the episode record in the store, ledger episode_end, trace."""
    with STATE_LOCK:
        grades, failed = dict(RUN["grades"]), list(RUN["failed"])
    total, cost = 0, 0.0
    bt = {"input": 0, "cached": 0, "output": 0, "reasoning": 0}
    for line in read(os.path.join(PD, "ledger.jsonl")).splitlines():
        try:   # a ledger line an agent appended (not an object, odd types) is skipped
            e = json.loads(line)
            if isinstance(e, dict) and e.get("kind") == "call":
                n_tok, n_cost = int(e.get("tokens") or 0), float(e.get("cost_usd") or 0)
                us = dict((k, int((e.get("usage") or {}).get(k, 0) or 0)) for k in bt)
                total, cost = total + n_tok, cost + n_cost
                for k in bt:
                    bt[k] += us[k]
        except Exception:
            continue
    try:
        json.dump({"agent": "pece-dsh", "harness": "ra3_%s" % ORCH_VERSION, "model": MODEL, "total_tokens": total, "billed_input_tokens": bt["input"],
                   "billed_cached_tokens": bt["cached"], "billed_output_tokens": bt["output"], "billed_reasoning_tokens": bt["reasoning"],
                   "cost_usd": round(cost, 4), "rates_per_mtok": {"uncached_input": RATES[0], "cached_input": RATES[1], "output": RATES[2]},
                   "cost_note": "estimated: per-call dsh session usage x RA3SR_RATES (settle from .dsh_ra3 sessions for the billed figure)"},
                  open(os.path.join(WS, "token_usage.json"), "w"), indent=2)
    except Exception as e:
        log("token_usage.json write failed: %s" % e)
    ed = os.path.join(STORE, "episodes", RUN_ID)
    try:   # the digest in its own step: a ledger line it cannot read never costs the episode record below
        build_digest()
    except Exception as e:
        log("digest failed: %s" % e)
    try:
        os.makedirs(os.path.join(ed, "critic"), exist_ok=True)
        if os.path.exists(os.path.join(PD, "digest.md")):
            shutil.copy(os.path.join(PD, "digest.md"), ed)
        json.dump({"paper": PAPER, "workdir": os.environ.get("HOST_WORK_DIR", ""), "grades": grades, "failed": failed, "ts": int(time.time()),
                   "override": OVERRIDE.is_set(), "report": REPORT, "infra_dead": INFRA["dead"]}, open(os.path.join(ed, "meta.json"), "w"), indent=2)
        for uid in grades:
            p = os.path.join(unit_dir(uid), "critic_report.md")
            if os.path.exists(p):
                shutil.copy(p, os.path.join(ed, "critic", "%s_critic_report.md" % uid))
    except Exception as e:
        log("episode record failed: %s" % e)
    ledger({"kind": "episode_end", "grades": grades, "failed": failed, "deliverables": deliverables_ok(), "calls": CALLS["n"], "override": OVERRIDE.is_set(),
            "report_mode": REPORT.get("reason"), "cost_usd": round(cost, 4), "infra_dead": INFRA["dead"]})
    log("episode done: grades=%s deliverables=%s calls=%d override=%s cost=$%.2f" % (grades, deliverables_ok(), CALLS["n"], OVERRIDE.is_set(), cost))
    build_trace()

# ---------------------------------------------------------------- main
def _requeued():
    """A scheduler requeue restarts the job in the SAME workspace: an episode that already started here is never run twice."""
    try:
        for line in read(os.path.join(PD, "ledger.jsonl")).splitlines():
            if '"episode_start"' in line and json.loads(line).get("kind") == "episode_start":
                return True
    except Exception:
        pass
    return False

def _on_stop(signum, frame=None):
    """Handler of SIGTERM, SIGINT and SIGHUP. No new dsh session starts (ABORT; STOP and OVERRIDE wind the threads down), every
    process of the run is killed (_sweep_run: twice, half a second apart, and a third time when the second still found one), the
    ledger records orchestrator_stopped and the process exits with 128 + signum. No report is written. A second signal during the
    stop is ignored. Every write is guarded: the handler runs in the main thread between two bytecodes."""
    if ABORT.is_set():
        return
    ABORT.set()
    STOP.set()
    OVERRIDE.set()
    swept = []
    for i in range(3):
        if i:
            time.sleep(0.5)
        try:
            swept.append(_sweep_run())
        except Exception:
            swept.append(0)
        if i and not swept[-1]:
            break
    try:
        name = signal.Signals(signum).name
    except Exception:
        name = str(signum)
    try:
        ledger({"kind": "orchestrator_stopped", "signal": name, "swept": swept, "calls": sorted(ACTIVE_CALLS)[:20]})
    except Exception:
        pass
    try:
        log("STOPPED by %s: %d process(es) of this run killed; no report is written" % (name, sum(swept)))
    except Exception:
        pass
    os._exit(128 + signum)

def _install_stop_handlers():
    """_on_stop for SIGTERM, SIGINT and SIGHUP, except for a signal the caller already ignores (under nohup SIGHUP stays ignored).
    Only the main thread can install handlers; elsewhere nothing is installed. Returns the names of the signals now handled."""
    done = []
    for name in ("SIGTERM", "SIGINT", "SIGHUP"):
        sig = getattr(signal, name, None)
        try:
            if sig is None or signal.getsignal(sig) == signal.SIG_IGN:
                continue
            signal.signal(sig, _on_stop)
            done.append(name)
        except (ValueError, OSError):
            pass
    return done

def _main_body():
    global POOL
    if not os.path.isdir(NOTES_DIR):   # no memory folder: stop before any write (a folder that lacks some files is the ablation switch)
        log("CONFIGURATION ERROR: the memory folder %s does not exist. Set RA3SR_NOTES_DIR to a folder with planner_notes.md, "
            "critic_notes.md, residual_bank.md and libraries.md (the shipped ones are in residual_agents/memories/). Nothing was written."
            % NOTES_DIR)
        sys.exit(2)
    if not _shim_on() and not os.environ.get("DEEPSEEK_API_KEY", "").strip():   # direct mode without a key: stop before any write
        log("CONFIGURATION ERROR: direct mode (RA_DSH_SHIM is not 1) needs DEEPSEEK_API_KEY (DEEPSEEK_BASE_URL defaults to "
            "https://api.deepseek.com); set it, or run through the local proxy with RA_DSH_SHIM=1. Nothing was written.")
        sys.exit(2)
    _install_stop_handlers()   # a stop signal kills every process of the run (an ignored signal stays ignored)
    os.makedirs(PD, exist_ok=True)
    if _requeued():
        mk = os.path.join(WS, ".infra_failure")
        try:
            with open(mk, "a") as f:
                f.write("requeue: a second episode_start in the same workspace refused | node=%s\n" % os.uname().nodename)
        except Exception:
            pass
        ledger({"kind": "requeue_refused", "reason": "the ledger already holds an episode_start"})
        log("REQUEUE REFUSED: this workspace already ran an episode - exiting (infra policy: void + clean rerun)")
        INFRA["dead"] = True
        return "requeue"
    POOL = ResourcePool(NCPUS, MEM_GB)
    threading.Thread(target=rss_sampler, name="rss", daemon=True).start()
    log("RA %s episode %s paper %s wall=%ds model=%s ncpus=%d mem_gb=%s gpus=%s plan_only=%s report_min=%d"
        % (ORCH_VERSION, RUN_ID, PAPER, WALL, MODEL, NCPUS, MEM_GB, gpu_facts() or "none", PLAN_ONLY, REPORT_MIN))
    log("node: %d cores (%s), %s GB memory (%s)" % (NCPUS, NODE_SRC.get("ncpus", "?"), MEM_GB, NODE_SRC.get("mem_gb", "?")))
    # "epic_shim" (true = dsh used the local proxy): key name kept for compatibility with the published ledgers
    ev = {"kind": "episode_start", "wall": WALL, "model": MODEL, "harness": "ra3", "version": ORCH_VERSION, "orch": ORCH_VERSION, "orch_patch": ORCH_VERSION,
          "backend": BACKEND, "ncpus": NCPUS, "mem_gb": MEM_GB, "mask": len(_affinity()), "exec_slice_s": EXEC_SLICE_S, "cp_s": CP_S,
          "vision_ok": VISION_OK, "gpus": [list(x) for x in gpu_facts()], "dsh_model": _dsh_model(), "epic_shim": _shim_on(), "dsh_version": _dsh_version(),
          "smoke_force_c": SMOKE_FORCE_C, "min_attempt_s": MIN_ATTEMPT_S, "last_act_s": LAST_ACT_S, "scout_t": SCOUT_T, "scout_select_t": SCOUT_SELECT_T,
          "scout_need_s": SCOUT_NEED_S, "report_min": REPORT_MIN}
    ledger(ev)
    items = task_book_items()
    ledger({"kind": "task_book", "items": len(items), "sections": sorted(set(sec for _, sec, _ in items))[:12], "report_cost_min": report_cost_min()})
    load_notes()
    plan = get_plan()
    if INFRA["dead"]:
        return "infra"
    with STATE_LOCK:
        RUN["plan"] = plan or []
    how = "normal"
    if RUN["plan"]:
        checkpoint()
        ov = threading.Thread(target=override_thread, name="override", daemon=True)
        ov.start()
        how = schedule_loop()
        if how == "override":
            flush_wait()
    if INFRA["dead"]:
        return "infra"
    run_report(how)
    return how

def main():
    """Every exit path ends in a report (an episode without report.md scores 0) unless the backend is dead or the job was requeued - those
    are infra failures the rerun policy re-issues clean."""
    how = None
    try:
        how = _main_body()
    except SystemExit:
        raise
    except Exception as e:
        import traceback
        log("MAIN THREAD FAILED: %s\n%s" % (e, traceback.format_exc()[-2000:]))
        have = os.path.exists(os.path.join(WS, "report.md"))
        ledger({"kind": "main_exception", "error": str(e)[:300], "report_existed": have})
        if not have and not INFRA["dead"]:
            try:
                fire_override("main_exception")
                flush_wait()
            except Exception as e1:
                log("last-resort flush failed: %s" % e1)
            try:
                run_report("override")
            except Exception as e2:
                log("last-resort report failed: %s" % e2)
    STOP.set()
    if how != "requeue":
        try:
            epilogue()
        except Exception as e3:
            log("epilogue failed: %s" % e3)
    if os.path.exists(os.path.join(WS, ".infra_failure")):   # exit 3 = an infra failure the rerun policy re-issues (a delivered report is never one)
        sys.exit(3)

if __name__ == "__main__":
    main()
